(window.NTDATA=window.NTDATA||{});(NTDATA.arar=NTDATA.arar||{}).acts={"1":{"1":"Առաջին գիրքը, որ գրեցի, այն ամենի մասին էր, ո՛վ Թեոփիլե, ինչ Հիսուսը սկզբից արեց և ուսուցանեց","2":"մինչև այն օրը, երբ Սուրբ Հոգու միջոցով իր ընտրյալ առաքյալներին պատվիրեց և համբարձվեց,","3":"որոնց իսկ իր չարչարանքներից հետո բազում ապացույցներով կենդանի ներկայանալով՝ քառասուն օրերի ընթացքում հայտնվեց նրանց և Աստծու արքայության մասին խոսեց։","4":"Որքան ժամանակ որ միասին էին, Հիսուսը նրանց պատվիրում էր. «Չհեռանա՛ք Երուսաղեմից, այլ Հոր խոստմա՛նը սպասեք, ինչպես որ ինձանից լսեցիք.","5":"որովհետև չնայած Հովհաննեսը մկրտում էր ջրով, իսկ դուք սրանից ոչ շատ օրեր հետո կմկրտվեք Սուրբ Հոգով»։","6":"Աշակերտներն իրար միացան և նրան հարցրին՝ ասելով. «Տե՛ր, այս ժամանա՞կ ես Իսրայելի թագավորությունը վերահաստատելու»։","7":"Եվ Հիսուսն ասաց նրանց. «Ձեր գործը չէ ժամերն ու ժամանակներն իմանալը, որ Հայրն իր իշխանությամբ սահմանեց։","8":"Բայց դուք զորություն կստանաք, երբ Հոգին ձեզ վրա գա, և իմ վկաները կլինեք Երուսաղեմում, ամբողջ Հրեաստանում ու Սամարիայում, մինչև աշխարհի ծայրերը»։","9":"Այս ասելուց հետո, մինչ նրանք նայում էին, Հիսուսը վեր բարձրացավ, և ամպը նրան ծածկեց նրանց աչքերից։","10":"Եվ մինչ նրանք իրենց հայացքը սևեռել էին դեպի երկինք և Հիսուսի գնալուն էին նայում, ահա սպիտակ զգեստներով երկու մարդ երևացին","11":"և նրանց ասացին. «Ո՛վ գալիլեացիներ, ի՞նչ եք կանգնել ու երկինք նայում։ Այս Հիսուսը, որ ձեր միջից երկինք համբարձվեց, նույն կերպ էլ պիտի գա, ինչպես որ նրան տեսաք երկինք գնալիս»։","12":"Այդ ժամանակ նրանք Երուսաղեմ վերադարձան Ձիթենյաց կոչվող լեռան վրայից, որը մոտ էր Երուսաղեմին և գտնվում էր մի շաբաթ օրվա ճանապարհի չափ հեռավորության վրա։","13":"Երբ քաղաք մտան, բարձրացան վերնատուն, որտեղ մնում էին Պետրոսն ու Հակոբոսը, Հովհաննեսն ու Անդրեասը, Փիլիպպոսն ու Թովմասը, Բարթողոմեոսն ու Մատթեոսը, Ալփեոսի որդի Հակոբոսն ու Սիմոն Նախանձահույզը և Հակոբոսի որդի Հուդան։","14":"Սրանք բոլորը միշտ միաբան աղոթքի մեջ էին մի քանի կանանց, Հիսուսի մոր՝ Մարիամի և նրա եղբայրների հետ միասին։","15":"Եվ այդ օրերին Պետրոսը վեր կացավ կանգնեց եղբայրների մեջ (այնտեղ հարյուր քսան հոգու չափ բազմություն կար) և ասաց.","16":"«Եղբայրնե՛ր, պետք է իրականանար գրվածը, որ Սուրբ Հոգին Դավթի բերանով նախապես ասել էր Հուդայի մասին, որը Հիսուսին ձերբակալողներին ուղեկցողը եղավ։","17":"Որովհետև նա էլ մեզանից մեկն էր և մասնակից էր այս ծառայությանը։","18":"Արդ, նա իր անիրավության վարձով մի ագարակ ստացավ ու գլխիվայր ընկնելով՝ մեջտեղից պատռվեց, և նրա ամբողջ փորոտիքը դուրս թափվեց։","19":"Եվ Երուսաղեմի բոլոր բնակիչներին սա հայտնի դարձավ, այնպես որ այդ ագարակն իրենց բարբառով Ակեղդամա կոչվեց, այսինքն՝ \"Արյան ագարակ\"։","20":"Քանի որ Սաղմոսների գրքում գրված է. \"Թող նրա տունն ավերակ դառնա, և ոչ ոք թող այնտեղ չբնակվի\" (Սաղ. 69.25), և \"Թող նրա առաքելությունն ուրիշն առնի\" (Սաղ. 109.8)։","21":"Արդ, պետք է, որ այստեղ եղած մարդկանցից մեկը, որոնք մեզ հետ են եղել այն ամբողջ ժամանակ, երբ Տեր Հիսուսը մեզ հետ էր՝","22":"սկսած Հովհաննեսի մկրտությունից մինչև այն օրը, երբ մեզանից համբարձվեց, նա պետք է մեզ հետ միասին նրա հարության վկան լինի»։","23":"Եվ ներկայացրեցին երկու հոգու՝ Հովսեփին, որ Բարսաբբաս էր կոչվում և Հուստոս անվանվեց, ու Մատաթիային։","24":"Եվ աղոթելով ասացին. «Դու, Տե՛ր, որ գիտես բոլորի սրտերը, հայտնի՛ր, թե այս երկուսից ո՛ւմ ես ընտրել","25":"այս ծառայությանը և առաքելությանը մասնակից լինելու, որից Հուդան ընկավ և իր տեղը գնաց»։","26":"Եվ նրանց մեջ վիճակ գցեցին. վիճակը Մատաթիային ընկավ, և նա գումարվեց տասնմեկ առաքյալներին։"},"2":{"1":"Եվ Պենտեկոստեի օրը բոլորը միասին գտնվում էին նույն տեղում։","2":"Հանկարծ երկնքից սաստիկ քամու պես մի ձայն հնչեց և լցրեց ամբողջ տունը, որտեղ նստած էին։","3":"Եվ նրանց երևացին բաժանված հրե լեզուներ, որոնք նստեցին նրանցից յուրաքանչյուրի վրա։","4":"Բոլորը լցվեցին Սուրբ Հոգով և սկսեցին ուրիշ լեզուներով խոսել, ինչպես որ նրանց խոսել էր տալիս Հոգին։","5":"Երուսաղեմում բնակվում էին աստվածավախ հրեաներ երկնքի տակ գտնվող բոլոր ազգերից։","6":"Երբ այդ ձայնը հնչեց, բազմություն հավաքվեց ու խռնվեց, որովհետև լսում էին, որ նրանք խոսում են իրենցից յուրաքանչյուրի լեզվով։","7":"Բոլորը հիացած ու զարմացած միմյանց ասում էին. «Ահա սրանք բոլորը, որ խոսում են, գալիլեացի չե՞ն։","8":"Ինչպե՞ս է, որ մեզնից ամեն մեկը լսում է իր մայրենի լեզուն։","9":"Մենք՝ պարթևներ ու մարեր, էլամացիներ ու Միջագետքում, Հրեաստանում ու Կապադովկիայում, Պոնտոսում ու Ասիայում,","10":"Փռյուգիայում ու Պամփյուլիայում, Եգիպտոսում ու Կյուրենյան Լիբիայի շրջաններում բնակվողներ ու հռոմեացի եկվորներ,","11":"հրեաներ թե նորադարձներ, կրետացիներ ու արաբներ, լսում ենք, որ նրանք մեր լեզուներով Աստծու մեծագործությունների մասին են խոսում»։","12":"Բոլորը զմայլված և զարմացած հարցնում էին միմյանց. «Սա ի՞նչ կարող է լինել»։","13":"Իսկ ուրիշները ծաղրելով ասում էին. «Քաղցր գինով են հարբել»։","14":"Եվ Պետրոսը տասնմեկի հետ վեր կացավ, իր ձայնը բարձրացրեց և նրանց ասաց. «Ո՛վ հրեաստանցիներ և բոլո՛րդ, որ Երուսաղեմում եք ապրում. սա թող հայտնի լինի ձեզ, և ակա՛նջ դրեք իմ խոսքերին։","15":"Սրանք հարբած չեն, ինչպես դուք եք կարծում, քանի որ օրվա երրորդ ժամն է,","16":"այլ սա այն է, ինչ ասվել է Հովել մարգարեի միջոցով.","17":"\"Եվ վերջին օրերին,- ասում է Աստված,- իմ Հոգուց պիտի հեղեմ ամեն մարմնի վրա, և ձեր որդիներն ու դուստրերը պիտի մարգարեանան. ձեր երիտասարդները տեսիլքներ, իսկ ձեր ծերերը երազներ պիտի տեսնեն։","18":"Եվ իմ ծառաների ու աղախինների վրա ևս այդ օրերին իմ Հոգուց պիտի հեղեմ, և պիտի մարգարեանան։","19":"Եվ պիտի ցույց տամ հրաշքներ վերը՝ երկնքում, և նշաններ՝ ներքևում՝ երկրի վրա. արյուն, կրակ ու ծխի սյուն։","20":"Արեգակը պիտի փոխակերպվի խավարի, և լուսինը՝ արյան, քանի դեռ չի եկել Տիրոջ մեծ ու երևելի օրը։","21":"Եվ այնպես պիտի լինի, որ ամեն ոք, ով Տիրոջ անունը կանչի, պիտի փրկվի\" (Հվլ. 2.28-32)։","22":"Ո՛վ իսրայելացիներ, լսե՛ք այս խոսքերը. Հիսուս Նազովրեցուն Աստված ձեզ ցույց տվեց զորությամբ, հրաշքներով ու նշաններով, որոնք Աստված, ինչպես դուք արդեն գիտեք, ձեր մեջ կատարեց նրա միջոցով.","23":"նրան Աստծու սահմանած խորհրդով ու կանխագիտությամբ անօրենների ձեռքը մատնեցիք և փայտի վրա գամելով՝ սպանեցիք։","24":"Նրան Աստված հարություն տվեց՝ մահվան կապանքները քանդելով, քանի որ անհնար էր, որ մահն իշխեր նրան։","25":"Իրապես Դավիթը Հիսուսի մասին է ասում. \"Տիրոջն ամեն ժամ տեսնում էի իմ առաջ, որն իմ աջ կողմում է, որպեսզի չսասանվեմ։","26":"Դրա համար իմ սիրտն ուրախացավ, լեզուս ցնծաց, մարմինս էլ հույսով պիտի ապրի։","27":"Որովհետև իմ մարմինը գերեզմանում չես թողնի և թույլ չես տա, որ քո Սուրբը ապականություն տեսնի։","28":"Ինձ ցույց տվեցիր կյանքի ճանապարհները և ինձ քո ներկայության ուրախությամբ պիտի լցնես\" (Սաղ. 16.8-11)։","29":"Եղբայրնե՛ր, ձեզ պետք է Դավիթ նահապետի մասին համարձակաբար ասեմ, որ նա և՛ մեռավ, և՛ թաղվեց, ու նրա գերեզմանը մինչև այսօր մեր մեջ է։","30":"Արդ, մարգարե լինելով՝ նա գիտեր, որ Աստված իրեն երդմամբ խոստացավ իր որովայնի պտղից մեկին նստեցնել իր աթոռին (Սաղ. 132.11, Բ Թագ. 7.12),","31":"ուստի կանխավ տեսնելով՝ նա խոսեց Քրիստոսի հարության մասին. \"Նա գերեզմանում չթողնվեց, ոչ էլ նրա մարմինն ապականություն տեսավ\"։","32":"Այս Հիսուսին Աստված հարություն տվեց, որին մենք ամենքս վկա ենք։","33":"Արդ Աստծու զորությամբ բարձրանալով՝ Հորից ստացավ խոստացված Սուրբ Հոգին, որը հեղեց մեզ վրա, և դուք հիմա այն տեսնում ու լսում եք։","34":"Դավիթը, որ երկինք չէր բարձրացել, ինքն իսկ ասում է. \"Տերն իմ Տիրոջն ասաց. Նստի՛ր իմ աջ կողմում,","35":"մինչև որ թշնամիներիդ ոտքերիդ տակ իբրև պատվանդան դնեմ\" (Սաղ. 110.1)։","36":"Արդ Իսրայելի ամբողջ տունը թող վստահաբար իմանա, որ Աստված նրա՛ն և՛ Տեր, և՛ Օծյալ արեց, այն Հիսուսին, որին դուք խաչը հանեցիք»։","37":"Երբ նրանք այս լսեցին, իրենց սրտում զղջացին և Պետրոսին ու մյուս առաքյալներին ասացին. «Ի՞նչ պիտի անենք, եղբայրնե՛ր»։","38":"Պետրոսը նրանց ասաց. «Ապաշխարե՛ք, և ձեզանից յուրաքանչյուրը մեղքերի թողության համար թող Հիսուս Քրիստոսի անունով մկրտվի, և դուք Սուրբ Հոգու պարգևը պիտի ստանաք։","39":"Որովհետև այս խոստումը ձեզ, ձեր զավակների և բոլոր այն հեռավորների համար է, որոնց մեր Տեր Աստվածը կանչելու է»։","40":"Պետրոսն ուրիշ շատ խոսքերով էլ էր վկայում և նրանց մխիթարում՝ ասելով. «Փրկե՛ք ձեզ այս խոտոր սերնդից»։","41":"Ովքեր նրա խոսքը հոժարությամբ ընդունեցին, մկրտվեցին։ Եվ այդ օրը նրանք երեք հազար հոգով ավելացան։","42":"Ջերմեռանդորեն հետևում էին առաքյալների ուսուցմանը, հաղորդությանը, հացի բեկմանը և աղոթքներին։","43":"Նրանք բոլորը վախով էին համակված, որովհետև առաքյալների միջոցով շատ հրաշքներ ու նշաններ էին կատարվում։","44":"Բոլոր հավատացյալները նույն տեղում էին համախմբվում, և նրանց ողջ ունեցածն ընդհանուր էր։","45":"Նրանք վաճառում էին իրենց ունեցվածքն ու կալվածքները և բաժանում էին բոլորին. ով ինչի կարիք ունենար։","46":"Ամեն օր տաճարում էին համախմբվում, իսկ հացի բեկումը տներում էին կատարում՝ ուրախությամբ և պարզ սրտով իրենց կերակուրը ճաշակելով։","47":"Օրհնում էին Աստծուն և ամբողջ ժողովրդի մեջ սեր ու հարգանք էին վայելում։ Իսկ Տերը նրանց խմբում փրկվածների էր ավելացնում ամեն օր։"},"3":{"1":"Պետրոսն ու Հովհաննեսը բարձրանում էին տաճար՝ իններորդ ժամի աղոթքի համար։","2":"Ի ծնե կաղ մի մարդ կար, որին ամեն օր բերում էին տաճարի դռան մոտ, որ «Գեղեցիկ» էր կոչվում, որպեսզի նա տաճար մտնողներից ողորմություն խնդրեր։","3":"Երբ նա տեսավ Պետրոսին ու Հովհաննեսին տաճար մտնելիս, ողորմություն խնդրեց նրանցից։","4":"Պետրոսը Հովհաննեսի հետ նայեց նրան ու ասաց. «Մե՛զ նայիր»։","5":"Նա հայացքը նրանց վրա սևեռեց՝ ինչ-որ բան նրանցից վերցնելու ակնկալիքով։","6":"Պետրոսն ասաց. «Արծաթ ու ոսկի չունեմ, բայց ինչ ունեմ, քեզ կտամ։ Հանուն Նազովրեցի Հիսուս Քրիստոսի վե՛ր կաց և քայլի՛ր»։","7":"Եվ նա, բռնելով նրա աջ ձեռքից, նրան ոտքի կանգնեցրեց, և նրա սրունքներն ու ազդրերն իսկույն ամրացան։","8":"Նա ցատկելով ոտքի կանգնեց ու քայլեց և նրանց հետ տաճար մտավ՝ քայլելով, ցատկելով ու Աստծուն օրհնելով։","9":"Ամբողջ ժողովուրդը տեսավ նրան, որ քայլում էր և օրհնում Աստծուն։","10":"Եվ ճանաչում էին նրան, որ ողորմության համար նստում էր տաճարի «Գեղեցիկ» դռան մոտ։ Եվ պատահածի համար լցվեցին երկյուղով ու զարմանքով։","11":"Մինչ նա Պետրոսին ու Հովհաննեսին բաց չէր թողնում, ամբողջ ժողովուրդը երկյուղած վազեց նրանց մոտ՝ այն սրահը, որ «Սողոմոնի սրահ» էր կոչվում։","12":"Երբ Պետրոսը տեսավ, ժողովրդին ասաց. «Ո՛վ իսրայելացիներ, ինչո՞ւ եք սրա վրա զարմացել կամ ինչո՞ւ եք ապշած մեզ վրա նայում, կարծես թե մենք մեր զորությամբ կամ բարեպաշտությամբ ենք նրան քայլել տվել։","13":"Աբրահամի, Իսահակի և Հակոբի Աստվածը՝ մեր հայրերի Աստվածը, փառավորեց իր Որդի Հիսուսին, որին դուք մատնեցիք ու Պիղատոսի առաջ ուրացաք, երբ նա վճռեց ազատ արձակել նրան։","14":"Դուք Սրբին ու Արդարին մերժեցիք և խնդրեցիք, որ ձեզ մի մարդասպանի շնորհի։","15":"Սպանեցիք կյանքի Առաջնորդին, որին Աստված մեռելներից հարություն տվեց, և մենք այդ բանին վկա եղանք։","16":"Հիսուսի անվան հանդեպ հավատը ոտքի կանգնեցրեց սրան, որին դուք տեսնում և ճանաչում եք, և նրանով հավատը ձեր բոլորի առաջ սրան այս առողջությունը տվեց։","17":"Եվ այժմ, եղբայրնե՛ր, գիտեմ, որ ինչպես դուք, այնպես էլ ձեր իշխանավորները անգիտությամբ արեցին։","18":"Բայց Աստված ինչ որ իր բոլոր մարգարեների բերանով նախապես հայտնել էր Քրիստոսի չարչարվելու մասին, այնպես էլ կատարեց։","19":"Արդ ապաշխարե՛ք ու դարձի՛ եկեք,","20":"որպեսզի ձեր մեղքերը ջնջվեն, որպեսզի Տիրոջից հանգստյան ժամանակները գան, և նա ուղարկի վաղօրոք ձեզ համար քարոզված Հիսուս Քրիստոսին.","21":"նա պետք է մնա երկնքում այնքան ժամանակ, մինչև իրականանա այն ամենը, ինչի մասին Աստված դարեր առաջ խոսեց իր սուրբ մարգարեների բերանով։","22":"Նախ Մովսեսն է ասել. \"Ձեր Տերը՝ Աստվածը, ձեր եղբայրների միջից ինձ նման մի մարգարե պիտի հանի. նրան պիտի լսեք ամեն ինչում, ինչ էլ ձեզ ասի։","23":"Եվ ամեն մարդ, ով այդ մարգարեին չլսի, ժողովրդի միջից պիտի բնաջնջվի\" (Բ Օր. 18.15-19)։","24":"Սկսած Սամուելից՝ նրան հաջորդած բոլոր մարգարեները կանխասացին այս օրերի մասին։","25":"Դուք եք որդիները մարգարեների և այն ուխտի, որ Աստված մեր հայրերի հետ հաստատեց և Աբրահամին ասաց. \"Եվ քո սերնդով պիտի օրհնվեն երկրի բոլոր ազգերը\" (Ծնն. 22.18)։","26":"Աստված նախ ձեզ համար հարություն տվեց իր Որդի Հիսուսին և ուղարկեց նրան ձեզ օրհնելու՝ յուրաքանչյուրիդ իր չար գործերից հետ դարձնելով»։"},"4":{"1":"Նրանք տակավին խոսում էին ժողովրդի հետ, երբ նրանց վրա հասան քահանաները, տաճարի պահակապետը և սադուկեցիները՝","2":"սաստիկ զայրացած, որ սրանք Հիսուսի օրինակով ժողովրդին ուսուցանում և քարոզում էին մեռելներից հարության մասին։","3":"Եվ նրանց ձերբակալեցին ու բանտարկեցին մինչև հաջորդ օրը, որովհետև արդեն երեկո էր։","4":"Սակայն խոսքը լսողներից շատերը հավատացին, և հավատացյալների թիվը շուրջ հինգ հազար եղավ։","5":"Հաջորդ օրը նրանց իշխանավորները, ծերերն ու դպիրները հավաքվեցին Երուսաղեմում,","6":"նաև Աննաս քահանայապետն ու Կայիափան, Հովհաննեսն ու Ալեքսանդրոսը և բոլոր նրանք, ովքեր քահանայական ցեղից էին։","7":"Եվ առաքյալներին մեջտեղում կանգնեցնելով՝ հարցնում էին. «Դուք դա ի՞նչ զորությամբ կամ ո՞ւմ անունով կատարեցիք»։","8":"Այդ ժամանակ Պետրոսը, Սուրբ Հոգով լցված, նրանց ասաց. «Ո՛վ ժողովրդի իշխանավորներ ու Իսրայելի ծերեր,","9":"եթե մենք այսօր մի տկար մարդու հանդեպ գործված բարիքի համար հարցաքննվում ենք, թե նա ումո՛վ բժշկվեց,","10":"արդ թող հայտնի լինի ձեզ բոլորիդ և Իսրայելի ամբողջ ժողովրդին, որ Նազովրեցի Հիսուս Քրիստոսի անունով, որին դուք խաչեցիք, և որին Աստված մեռելներից հարություն տվեց. նրանով է սա հիմա ձեր առաջ առողջացած կանգնել։","11":"Սա է ձեզանից՝ շինողներիցդ անարգված այն քարը, որ անկյունաքար դարձավ (Սաղ. 118.22)։","12":"Եվ ուրիշ մեկի միջոցով փրկություն չկա, որովհետև երկնքի տակ չկա մարդկանց տրված ուրիշ անուն, որով մենք կարող ենք փրկվել»։","13":"Եվ Պետրոսի ու Հովհաննեսի համարձակությունը տեսնելով և հասկանալով, որ անուսում ու տգետ մարդիկ են, զարմացած էին, որովհետև նրանց ճանաչում էին իբրև Հիսուսի հետևորդների։","14":"Տեսնում էին նաև այն բժշկված մարդուն՝ կանգնած նրանց հետ, և պատասխանելու ոչինչ չունեին։","15":"Նրանց հրամայեցին ատյանից դուրս գալ և միմյանց հետ խորհրդակցեցին՝","16":"ասելով. «Ի՞նչ անենք այս մարդկանց, քանի որ սրանց ձեռքով երևելի հրաշք է գործվել, որը հայտնի է Երուսաղեմի բոլոր բնակիչներին, և մենք չենք կարող հերքել։","17":"Բայց որպեսզի ժողովրդի մեջ ավելի չտարածվի, նրանց խիստ սպառնանք, որ ոչ մի մարդու այդ անունով այլևս չքարոզեն»։","18":"Եվ նրանց կանչելով՝ պատվիրեցին Հիսուսի անունով բոլորովին չխոսել և չուսուցանել։","19":"Բայց Պետրոսն ու Հովհաննեսը նրանց պատասխանեցին և ասացին. «Մի՞թե Աստծու առաջ արդար է ավելի շատ ձեզ լսել, քան Աստծուն. դո՛ւք դատեք։","20":"Մենք չենք կարող չասել այն, ինչ տեսել ենք ու լսել»։","21":"Նրանք սպառնալով արձակեցին նրանց՝ ժողովրդի պատճառով ոչ մի միջոց չգտնելով նրանց պատժելու, որովհետև բոլորը կատարվածի համար փառք էին տալիս Աստծուն։","22":"Իսկ այն մարդը, որի վրա բժշկության այս նշանը կատարվեց, ավելի քան քառասուն տարեկան էր։","23":"Եվ ազատ արձակվելուց հետո առաքյալները յուրայինների մոտ եկան ու պատմեցին, թե քահանայապետներն ու ծերերն ինչեր ասացին իրենց։","24":"Նրանք, այս լսելով, միաբանված իրենց ձայնն առ Աստված բարձրացրին ու ասացին. «Տե՛ր Աստված, դու, որ ստեղծեցիր երկինքն ու երկիրը, ծովն ու նրա մեջ եղած ամեն բան,","25":"որ մեր հոր՝ Դավթի՝ քո ծառայի բերանով Սուրբ Հոգու միջոցով խոսեցիր ու ասացիր. \"Ինչո՞ւ հեթանոսները խռովվեցին, և ժողովուրդներն ունայն բաների մասին մտածեցին։","26":"Երկրի թագավորները վեր ելան, և իշխանները միասին հավաքվեցին Տիրոջ ու նրա Օծյալի դեմ\" (Սաղ. 2.1-2)։","27":"Արդարև, այս քաղաքում հավաքվեցին Հերովդեսը և Պոնտացի Պիղատոսը՝ հեթանոսների և Իսրայելի ժողովրդի հետ, քո սուրբ Որդի Հիսուսի դեմ, որին օծեցիր,","28":"որպեսզի անեն այն, ինչ քո ձեռքն ու կամքը նախապես սահմանել էին, որ լինի։","29":"Եվ այժմ, Տե՛ր, նայի՛ր նրանց սպառնալիքներին և քո ծառաներին ամենայն համարձակությամբ քո խո՛սքը խոսել տուր,","30":"որ քո ձեռքը մեկնես բժշկության համար, և նշաններ ու հրաշքներ էլ լինեն քո սուրբ Որդի Հիսուսի անունով»։","31":"Նրանց աղոթելուց հետո շարժվեց այն տեղը, որտեղ հավաքված էին, և բոլորը լցվեցին Սուրբ Հոգով ու Աստծու խոսքն էին քարոզում համարձակությամբ։","32":"Եվ հավատացյալների բազմությունը մեկ սիրտ ու մեկ հոգի էր. ոչ ոք չէր ասում, թե իր ունեցածներից ինչ-որ բան իրենն է, այլ ամեն ինչ նրանց համար ընդհանուր էր։","33":"Առաքյալները մեծ զորությամբ վկայում էին Տեր Հիսուսի հարության մասին, և նրանց բոլորի վրա մեծ շնորհ կար։","34":"Նրանց մեջ ոչ ոք որևէ բանի կարոտ չէր, քանի որ նրանք, ովքեր ագարակների կամ տների տեր էին, վաճառում էին դրանք և վաճառվածի գումարը","35":"առաքյալների տրամադրության տակ էին դնում, և յուրաքանչյուրին բաշխվում էր ըստ իր ունեցած կարիքի։","36":"Եվ Հովսեփը, որ առաքյալների կողմից Բառնաբաս կոչվեց (որ «Մխիթարության որդի» է թարգմանվում), ծնունդով կիպրացի մի ղևտացի էր։","37":"Նա մի ագարակ ուներ, որը վաճառեց և գումարը առաքյալների տրամադրության տակ դրեց։"},"5":{"1":"Անանիա անունով մի մարդ իր կնոջ՝ Սափիրայի հետ մի ագարակ վաճառեց","2":"և դրա գումարի մի մասը կնոջ իմացությամբ թաքցրեց, իսկ մյուս մասը բերեց, առաքյալների տրամադրության տակ դրեց։","3":"Պետրոսն ասաց. «Անա՛նիա, ինչո՞ւ սատանան քո սիրտը լցրեց, որ դու Սուրբ Հոգուն ստես և ագարակի գումարից թաքցնես։","4":"Չէ՞ որ քանի դեռ այն կար, քոնն էր, և վաճառելիս էլ կարող էիր գումարը քեզ պահել։ Ինչո՞ւ սրտիդ մեջ այդ բանը դրեցիր. դու ոչ թե մարդկանց ստեցիր, այլ Աստծուն»։","5":"Եվ Անանիան, այս խոսքերը լսելով, ընկավ ու շունչը փչեց։ Եվ մեծ ահ պատեց բոլոր նրանց, ովքեր դա լսեցին։","6":"Երիտասարդները վեր կացան, պատանեցին նրան և տարան թաղեցին։","7":"Շուրջ երեք ժամ անց նրա կինը, որ չգիտեր տեղի ունեցածի մասին, ներս մտավ։","8":"Պետրոսը նրան ասաց. «Ասա՛ ինձ, ագարակն այսքանո՞վ վաճառեցիք»։ Նա ասաց. «Այո՛, այդքանով»։","9":"Պետրոսը նրան ասաց. «Ինչո՞ւ միաբանվեցիք՝ Տիրոջ Հոգին փորձելու։ Ահա ամուսնուդ թաղողների ոտքերը դռան մոտ են և քեզ էլ դուրս կհանեն»։","10":"Եվ նա իսկույն ընկավ նրա ոտքերի առաջ ու շունչը փչեց։ Ներս մտնելով՝ երիտասարդները նրան մեռած գտան և դուրս հանելով՝ իր ամուսնու մոտ թաղեցին։","11":"Եվ մեծ ահ պատեց ամբողջ եկեղեցուն և բոլոր նրանց, ովքեր այս լսեցին։","12":"Առաքյալների ձեռքով ժողովրդի մեջ շատ նշաններ ու հրաշքներ էին կատարվում, և բոլորը համախմբված՝ Սողոմոնի սրահում էին։","13":"Ուրիշներից ոչ ոք չէր համարձակվում նրանց հարել, բայց ժողովուրդը նրանց մեծարում էր։","14":"Եվ ավելի ու ավելի էր շատանում Տիրոջը հավատացող տղամարդկանց ու կանանց բազմությունը,","15":"այն աստիճան, որ հիվանդներին հրապարակներն էին հանում և իրենց պատգարակներով ու մահիճներով այնտեղ էին դնում, որպեսզի Պետրոսի անցնելու ժամանակ գոնե նրա ստվերը դրանցից մեկին հասներ։","16":"Եվ շրջակա քաղաքներից բազմությունը հավաքվում էր Երուսաղեմում. բերում էին հիվանդների ու պիղծ ոգիներից տառապողների, որոնք բոլորն էլ բժշկվում էին։","17":"Բայց քահանայապետը և բոլոր նրանք, ովքեր նրա հետ էին ու սադուկեցիների աղանդից, նախանձով լցվեցին։","18":"Եվ ձերբակալեցին առաքյալներին ու նրանց հրապարակայնորեն բանտ նետեցին։","19":"Բայց Տիրոջ հրեշտակը, գիշերով բանտի դռները բացելով, նրանց դուրս հանեց և ասաց.","20":"«Գնացե՛ք, տաճարի մե՛ջ կանգնեք և կյանքի այս բոլոր խոսքերը ժողովրդի՛ն հաղորդեք»։","21":"Եվ երբ լսեցին, առավոտյան տաճար մտան և ուսուցանում էին։ Եկավ քահանայապետը, և նրանք, որ իր հետ էին, և իսրայելացի ամբողջ ծերակույտի հետ ժողով գումարեցին ու մարդ ուղարկեցին բանտ՝ նրանց բերելու։","22":"Երբ սպասավորները եկան, բանտում նրանց չգտան. վերադարձան, պատմեցին","23":"ու ասացին. «Բանտն ամենայն ապահովությամբ փակված գտանք, իսկ պահապաններին՝ դռան մոտ կանգնած, բայց երբ բաց արեցինք, ներսում ոչ ոքի չգտանք»։","24":"Երբ քահանայապետն ու տաճարի պահակապետն այս խոսքերը լսեցին, նրանց վրա զարմացան, թե այդ ի՛նչ պետք է եղած լիներ։","25":"Եվ մեկը եկավ, նրանց պատմեց. «Ահա այն մարդիկ, որոնց բանտ էիք դրել, տաճարում կանգնած, ժողովրդին են ուսուցանում»։","26":"Այդ ժամանակ պահակապետը սպասավորների հետ գնաց և նրանց առանց բռնության բերեց, որովհետև վախենում էին ժողովրդից, որ չքարկոծվեն։","27":"Երբ նրանց բերեցին, ատյանում կանգնեցրին։ Քահանայապետը նրանց հարցրեց","28":"ու ասաց. «Ձեզ խստիվ չպատվիրեցի՞նք, որ այդ անունով չուսուցանեք։ Ահա Երուսաղեմը ձեր ուսմունքով լցրիք և ուզում եք այդ մարդու արյունը մեզ վրա գցել»։","29":"Պետրոսն ու առաքյալները պատասխանեցին և ասացին. «Պետք է առավել Աստծուն հնազանդվել, քան մարդկանց։","30":"Մեր հայրերի Աստվածը հարություն տվեց Հիսուսին, որին դուք փայտից կախելով սպանեցիք։","31":"Աստված իր աջով նրա՛ն որպես Առաջնորդ ու Փրկիչ բարձրացրեց, որպեսզի Իսրայելին ապաշխարություն և մեղքերի թողություն տա։","32":"Եվ մենք նրա այս խոսքերի վկան ենք, ինչպես նաև Սուրբ Հոգին, որ Աստված տվեց իրեն հնազանդվողներին»։","33":"Երբ նրանք այս լսեցին, խիստ զայրացան և խորհում էին նրանց սպանելու մասին։","34":"Բայց ատյանում վեր կացավ Գամաղիել անունով մի փարիսեցի, որն օրենքի ուսուցիչ էր՝ ամբողջ ժողովրդի կողմից պատվված, և հրամայեց, որ առաքյալներին կարճ ժամանակով դուրս հանեն։","35":"Եվ նրանց ասաց. «Ո՛վ իսրայելացիներ, զգո՛ւյշ եղեք, թե ի՛նչ եք անելու այս մարդկանց հետ։","36":"Որովհետև օրեր առաջ ելավ Թևդասը՝ իրեն երևելի մեկը ցույց տալով, և նրան շուրջ չորս հարյուր մարդ հարեց. ինքն սպանվեց, իսկ նրա համախոհները բաժան-բաժան եղան, և ոչ ոք չմնաց։","37":"Նրանից հետո մարդահամարի օրերին գալիլեացի Հուդան ելավ և իր հետևից շատ մարդկանց տարավ. նա ևս կորստյան մատնվեց, իսկ նրա համախոհները ցիրուցան եղան։","38":"Եվ հիմա ասում եմ ձեզ. այդ մարդկանցից հեռո՛ւ մնացեք և թողե՛ք նրանց, որովհետև եթե այդ խորհուրդը կամ այդ գործը մարդկանցից է, կքանդվի,","39":"բայց եթե Աստծուց է, չեք կարող քանդել. միգուցե աստվածամարտ էլ դառնաք»։ Նրանք հավանություն տվեցին նրան","40":"և կանչեցին առաքյալներին, ծեծեցին ու պատվիրեցին, որ Հիսուսի անունով չխոսեն, և նրանց արձակեցին։","41":"Իսկ նրանք ուրախանալով գնացին ատյանից, որովհետև նրա անվան համար էին անարգանքի արժանացել։","42":"Եվ ամեն օր չէին դադարում տաճարում ու տներում ուսուցանել և Հիսուս Քրիստոսի մասին ավետարանել։"},"6":{"1":"Այն օրերին, երբ աշակերտների թիվը շատացավ, հունախոս հրեաները տրտնջացին եբրայախոս հրեաների դեմ, որովհետև իրենց այրիներն անտեսվում էին ամենօրյա ծառայություն ստանալու ժամանակ։","2":"Արդ տասներկու առաքյալները հավաքեցին աշակերտներին ու ասացին. «Մեզ վայել չէ, որ Աստծու խոսքի քարոզությունը թողնենք և սեղաններ սպասարկենք։","3":"Եղբայրնե՛ր, ընտրե՛ք ձեր միջից բարի համբավ ունեցող, Սուրբ Հոգով և իմաստությամբ լի յոթ հոգու, որոնց կկարգենք այս ծառայության վրա։","4":"Իսկ մենք կնվիրվենք աղոթքին և խոսքի քարոզությանը»։","5":"Այս խոսքը հաճելի թվաց բոլորին, և ընտրեցին Ստեփանոսին, որ Սուրբ Հոգով ու հավատով լցված մարդ էր, ինչպես նաև Փիլիպպոսին, Պրոքորոնին, Նիկանորասին, Տիմոնին, Պարմենասին և անտիոքացի նորադարձ Նիկողայոսին։","6":"Նրանց առաքյալների առաջ կանգնեցրին և աղոթելով ձեռք դրեցին նրանց վրա։","7":"Եվ Աստծու խոսքն աճում էր, և աշակերտների թիվը Երուսաղեմում չափազանց մեծանում էր. քահանաներից շատերն էին հնազանդվում հավատին։","8":"Իսկ Ստեփանոսը, շնորհով ու զորությամբ լցված, մեծ հրաշքներ ու նշաններ էր գործում ժողովրդի մեջ։","9":"Ոմանք այն ժողովարանից, որ կոչվում էր «ազատագրվածների», կյուրենացիների ու ալեքսանդրիացիների, և ոմանք էլ, որ Կիլիկիայից ու Ասիայից էին, ելան Ստեփանոսի հետ վիճելու։","10":"Եվ չէին կարողանում հակադրվել այն իմաստությանը և Հոգուն, որով նա խոսում էր։","11":"Այդ ժամանակ մի քանի մարդկանց կաշառեցին, որ ասեն. «Մենք դրանից լսեցինք, որ Մովսեսին և Աստծուն հայհոյանքներ էր անում»։","12":"Նրանք գրգռեցին ժողովրդին, ծերերին ու դպիրներին. և հարձակվեցին, բռնեցին Ստեփանոսին ու ատյան տարան։","13":"Ապա սուտ վկաների կանգնեցրին, որոնք ասում էին. «Այս մարդը չի դադարում հայհոյական խոսքեր ասել այս սուրբ տեղի և օրենքի դեմ,","14":"որովհետև մենք նրանից լսեցինք, որ ասում էր. \"Հիսուս Նազովրեցին պիտի քանդի այս տեղը և փոխի այն ավանդույթները, որ Մովսեսը մեզ տվեց\"»։","15":"Ատյանում բոլոր նստածները, նայելով նրան, տեսան, որ նրա երեսը հրեշտակի երեսի պես էր։"},"7":{"1":"Եվ քահանայապետն ասաց. «Արդյոք այդ բաներն այդպե՞ս են»։","2":"Նա ասաց. «Եղբայրնե՛ր ու հայրե՛ր, լսե՛ք. փառքի Աստվածը երևաց մեր հայր Աբրահամին՝ Միջագետքում եղած ժամանակ, մինչև Խառանում նրա բնակություն հաստատելը,","3":"և նրան ասաց. \"Դո՛ւրս ել քո երկրից ու քո ազգատոհմից և արի՛ այն երկիրը, որ ես ցույց կտամ քեզ\" (Ծնն. 12.1)։","4":"Այդ ժամանակ նա դուրս եկավ քաղդեացիների երկրից, բնակվեց Խառանում։ Այնտեղից էլ նրա հոր մահվանից հետո նրան փոխադրեց այս երկիրը, որտեղ հիմա դուք բնակվում եք։","5":"Եվ այստեղ նրան ժառանգություն չտվեց, ոչ էլ անգամ մի ոտնաչափ հող, բայց նրան խոստացավ տալ այս տիրույթը, իսկ նրանից հետո՝ նրա սերնդին, չնայած որ Աբրահամը դեռ որդի չուներ։","6":"Եվ Աստված այսպես խոսեց. \"Նրա սերունդն օտար երկրում պանդուխտ պիտի լինի, նրան ծառա պիտի դարձնեն և չորս հարյուր տարի պիտի չարչարեն։","7":"Եվ այն ազգին, որին ծառա պիտի լինեն, ես պիտի դատեմ,- ասաց Աստված,- և դրանից հետո պիտի ելնեն և ինձ պիտի պաշտեն այս տեղում\" (հմմտ. Ծնն. 15.13-14)։","8":"Եվ նրան թլփատության ուխտը տվեց։ Ապա նա Իսահակին ծնեց և ութերորդ օրը նրան թլփատեց, և Իսահակը՝ Հակոբին, իսկ Հակոբը՝ տասներկու նահապետներին։","9":"Նահապետները, Հովսեփին նախանձելով, նրան Եգիպտոս վաճառեցին, բայց Աստված նրա հետ էր","10":"և նրան իր բոլոր նեղություններից ազատեց, Եգիպտոսի փարավոնի առաջ նրան շնորհ ու իմաստություն տվեց և նրան Եգիպտոսի ու իր ամբողջ տան վրա իշխան կարգեց։","11":"Ամբողջ Եգիպտոսի և Քանանի վրա սով ու մեծ նեղություն վրա հասավ, և մեր հայրերն ուտելիք չէին գտնում։","12":"Հակոբը, լսելով, որ Եգիպտոսում ցորեն կա, մեր հայրերին առաջին անգամ այնտեղ ուղարկեց։","13":"Իսկ երկրորդ անգամ Հովսեփն իրեն ճանաչել տվեց իր եղբայրներին, և Հովսեփի ազգը փարավոնին հայտնի դարձավ։","14":"Հովսեփը մարդ ուղարկեց, կանչել տվեց իր հայր Հակոբին և ամբողջ ազգատոհմին՝ յոթանասունհինգ հոգի։","15":"Հակոբը Եգիպտոս իջավ, որտեղ վախճանվեցին ինքը և մեր հայրերը։","16":"Նրանց մարմինները փոխադրվեցին Սյուքեմ և դրվեցին այն գերեզմանում, որ Աբրահամը արծաթով գնել էր Սյուքեմում Եմովրի որդիներից։","17":"Երբ մոտեցավ Աբրահամին Աստծու տված խոստման իրականացման ժամանակը, Եգիպտոսում ժողովուրդն աճեց ու բազմացավ,","18":"մինչև որ Եգիպտոսում ելավ մի ուրիշ թագավոր, որը Հովսեփին չէր ճանաչում։","19":"Նա մեր ազգի դեմ հնարքներ գործադրեց, մեր հայրերին չարչարեց՝ նրանց երեխաներին դուրս նետելով, որպեսզի չապրեն։","20":"Այդ ժամանակ ծնվեց Մովսեսը, որն Աստծու առաջ վայելուչ էր և որն իր հոր տանը երեք ամիս մեծացավ։","21":"Եվ երբ նրան դուրս նետեցին, փարավոնի աղջիկը նրան վերցրեց, իբրև իր որդու մեծացրեց նրան։","22":"Մովսեսը կրթվեց եգիպտացիների ողջ իմաստությամբ և զորավոր էր իր խոսքերով ու գործերով։","23":"Երբ նրա քառասուն տարին լրացավ, նա միտք հղացավ իր եղբայրների՝ իսրայելացիների մեջ շրջելու։","24":"Եվ անիրավված մեկին տեսնելով ու տուժածի վրեժը լուծելով՝ սպանեց եգիպտացուն։","25":"Նա կարծում էր, թե իր եղբայրները կհասկանան, որ Աստված իր ձեռքով նրանց փրկություն է տալու. բայց նրանք չհասկացան։","26":"Հաջորդ օրը տեսավ նրանց միմյանց հետ կռվելիս և նրանց հաշտեցնելով՝ ասաց. \"Մարդի՛կ, դուք եղբայրներ եք, ինչո՞ւ եք միմյանց նեղացնում\"։","27":"Սակայն նա, ով ընկերոջը նեղացնում էր, նրան առարկեց ու ասաց. \"Քեզ ո՞վ մեզ վրա իշխան ու դատավոր կարգեց։","28":"Մի՞թե դու ուզում ես ինձ էլ սպանել, ինչպես որ երեկ եգիպտացուն սպանեցիր\"։","29":"Մովսեսն այս խոսքի վրա փախավ ու Մադիամի երկրում պանդուխտ դարձավ, որտեղ երկու որդի ունեցավ։","30":"Երբ քառասուն տարին լրացավ, Սինա լեռան անապատում Տիրոջ հրեշտակը երևաց նրան մորենու կրակի բոցի մեջ։","31":"Այդ տեսնելով՝ Մովսեսը զարմացավ տեսիլքի վրա։ Եվ երբ մոտենում էր նայելու, Տիրոջ ձայնը լսվեց.","32":"\"Ես եմ քո հայրերի Աստվածը, Աբրահամի, Իսահակի և Հակոբի Աստվածը\"։ Եվ Մովսեսը, զարհուրելով, չէր համարձակվում նայել։","33":"Տերը նրան ասաց. \"Հանի՛ր ոտքերիդ կոշիկները, որովհետև այդ տեղը, որտեղ դու կանգնած ես, սուրբ հող է։","34":"Ես տեսա Եգիպտոսում իմ ժողովրդի չարչարանքները, լսեցի նրա հառաչանքը և իջա, որ նրան փրկեմ։ Այժմ արի՛, ես քեզ պիտի ուղարկեմ Եգիպտոս\"։","35":"Այն Մովսեսին, որին մերժեցին և ասացին. \"Ո՞վ քեզ իշխան ու դատավոր կարգեց մեզ վրա\", Աստված նրան որպես իշխան ու փրկիչ ուղարկեց հրեշտակի միջոցով, որ Մովսեսին երևաց մորենու միջից։","36":"Նա՛ դուրս հանեց նրանց և հրաշքներ ու նշաններ կատարեց Եգիպտոսի երկրում, Կարմիր ծովում և քառասուն տարի՝ անապատում։","37":"Այս Մովսեսն է, որ Իսրայելի որդիներին ասաց. \"Աստված ձեր եղբայրների միջից ձեզ համար ինձ նման մի մարգարե պիտի հանի. նրա՛ն լսեք\"։","38":"Նա՛ է, որ երբ ժողովուրդն անապատում էր, Սինա լեռան վրա խոսեց հրեշտակի և մեր հայրերի հետ. նա՛ ստացավ կյանքի պատգամները, որպեսզի մեզ տա։","39":"Մեր հայրերը չցանկացան նրան հնազանդ լինել, այլ մերժեցին ու մտքով դեպի Եգիպտոս դարձան։","40":"Եվ Ահարոնին ասացին. \"Մեզ համար աստվածնե՛ր կերտիր, որոնք կառաջնորդեն մեզ, որովհետև այդ Մովսեսը, որ Եգիպտոսի երկրից մեզ հանեց, չգիտենք՝ նրան ի՛նչ պատահեց\"։","41":"Եվ այդ օրերին մի հորթ ձուլեցին ու կուռքին զոհ մատուցեցին՝ ուրախանալով իրենց ձեռքի գործերով։","42":"Աստված երես դարձրեց ու թողեց նրանց, որ երկնքի զորություններին պաշտեն, ինչպես որ մարգարեների գրքում է գրված. \"Մի՞թե անապատում քառասուն տարի ինձ զոհեր ու ընծաներ մատուցեցիք, ո՛վ Իսրայելի տուն։","43":"Դուք կրեցիք Մողոքի վրանը, ձեր Հռեմփա աստծու աստղը և այն կուռքերը , որ շինեցիք նրանց երկրպագելու համար։ Արդ ես ձեզ պիտի փոխադրեմ Բաբելոնից այն կողմ\" (Ամս. 5.25-27)։","44":"Վկայության խորանը մեր հայրերի հետ անապատում էր. Մովսեսի հետ խոսողը հրամայել էր այն կառուցել ըստ այն օրինակի, որ Մովսեսը տեսել էր։","45":"Հաջորդ սերնդի մեր հայրերը Հեսուի հետ այն բերեցին այն ազգերի երկիրը, որոնց Աստված վտարել էր մեր հայրերի առաջից մինչև Դավթի օրերը։","46":"Նա Աստծու առաջ շնորհ գտավ ու խնդրեց Հակոբի Աստծու համար բնակարան հիմնել։","47":"Բայց Սողոմոնը նրա համար տուն շինեց։","48":"Սակայն Բարձրյալը ձեռակերտ տաճարներում չի բնակվում, ինչպես մարգարեն է ասում.","49":"\"Երկինքն իմ աթոռն է, երկիրը՝ իմ ոտքերի պատվանդանը։ Ինչպիսի՞ տուն պիտի շինեիք ինձ համար,- ասում է Տերը,- կամ ո՞րն է հանգիստ առնելու իմ տեղը.","50":"չէ՞ որ իմ ձեռքն է այս ամենը ստեղծել\" (Ես. 66.1-2)։","51":"Համառնե՛ր և սրտերով ու ականջներով անթլփատնե՛ր, դուք միշտ ընդդիմանում եք Սուրբ Հոգուն. ինչպես ձեր հայրերն էին, այնպես էլ դուք եք։","52":"Ձեր հայրերը մարգարեներից որի՞ն չհալածեցին. սպանեցին նրանց, ովքեր կանխավ հայտնեցին Արդարի գալստյան մասին, որի մատնիչներն ու սպանողները հիմա դուք եղաք.","53":"դուք, որ օրենքն ստացաք հրեշտակների պատվերով, բայց այն չպահեցիք»։","54":"Նրանք, այս խոսքերը լսելով, իրենց սրտերում զայրանում էին ու նրա վրա կրճտացնում ատամները։","55":"Իսկ նա, Սուրբ Հոգով լցված, դեպի երկինք նայեց ու տեսավ Աստծու փառքը և Հիսուսին՝ Աստծու աջ կողմում կանգնած։","56":"Եվ ասաց. «Ահա տեսնում եմ երկինքը բացված ու Մարդու Որդուն՝ Աստծու աջ կողմում կանգնած»։","57":"Իսկ նրանք, բարձրաձայն աղաղակելով, փակեցին իրենց ականջները և բոլորը միասին հարձակվեցին նրա վրա։","58":"Եվ նրան քաղաքից դուրս հանելով՝ քարկոծում էին. վկաներն իրենց զգեստները դնում էին մի երիտասարդի ոտքերի առաջ, որ Սողոս էր կոչվում։","59":"Մինչ Ստեփանոսին քարկոծում էին, նա խոսքն ուղղեց Հիսուսին՝ ասելով. «Տե՛ր Հիսուս, ընդունի՛ր իմ հոգին»։","60":"Ապա ծնկի եկավ ու բարձր ձայնով աղաղակեց. «Տե՛ր, այդ մեղքը նրանց մի՛ վերագրիր»։ Եվ այս ասելով՝ մահացավ։"},"8":{"1":"Սողոսն էլ էր համագործակից նրա սպանությանը։ Այդ օրը Երուսաղեմի եկեղեցու դեմ մեծ հալածանք եղավ. բոլորը ցրվեցին Հրեաստանի ու Սամարիայի գավառները, բացի առաքյալներից։","2":"Աստվածավախ մարդիկ թաղեցին Ստեփանոսին ու նրա վրա մեծ ողբ արեցին։","3":"Իսկ Սողոսը ավերում էր եկեղեցին. տնից տուն էր մտնում և տղամարդկանց ու կանանց քարշ տալով՝ բանտ էր նետում։","4":"Իսկ ցրվածները շրջում էին՝ Աստծու խոսքն ավետարանելով։","5":"Փիլիպպոսը, Սամարիայի մի քաղաք իջնելով, Քրիստոսին էր քարոզում նրանց։","6":"Ժողովրդի բազմությունը համախմբված լսում էր Փիլիպպոսի խոսքերը և տեսնում նրա կատարած նշանները,","7":"քանի որ շատերի միջից պիղծ ոգիները բարձրաձայն աղաղակելով դուրս էին գալիս, և բազում անդամալույծներ ու կաղեր էին բժշկվում։","8":"Եվ այդ քաղաքում մեծ ուրախություն եղավ։","9":"Այդ քաղաքում Սիմոն անունով մի մարդ կար, որ վաղուց մոգություն էր անում և սամարացի ժողովրդին զարմացնում էր՝ ասելով, թե ինքը մեծ մեկն է։","10":"Եվ բոլորը՝ փոքրից մեծ, նրան էին հետևում ու ասում. «Սա է Աստծու զորությունը, որ մեծ է կոչվում»։","11":"Նրան հետևում էին, որովհետև երկար ժամանակ մոգություններով զարմացրել էր նրանց։","12":"Բայց երբ հավատացին Փիլիպպոսին, որն Աստծու արքայության և Հիսուս Քրիստոսի անվան մասին էր ավետարանում, բոլորն էլ մկրտվում էին՝ թե՛ տղամարդ, թե՛ կին։","13":"Սիմոնն ինքն էլ հավատաց ու երբ մկրտվեց, միշտ Փիլիպպոսին էր հետևում. տեսնելով այն նշաններն ու մեծամեծ հրաշքները, որ կատարվում էին, զարմանում էր։","14":"Երբ Երուսաղեմում գտնվող առաքյալները լսեցին, որ Սամարիան ընդունել է Աստծու խոսքը, նրանց մոտ ուղարկեցին Պետրոսին ու Հովհաննեսին,","15":"որոնք այնտեղ իջան ու նրանց համար աղոթեցին, որպեսզի Սուրբ Հոգին ստանան.","16":"քանի որ նրանցից ոչ մեկի վրա դեռ չէր իջել, այլ միայն Տեր Հիսուսի անունով էին մկրտվել։","17":"Այդ ժամանակ ձեռքերը նրանց վրա դրեցին, և նրանք Սուրբ Հոգին ստացան։","18":"Սիմոնը, տեսնելով, որ առաքյալների ձեռք դնելով Սուրբ Հոգին տրվում է, նրանց փող առաջարկեց","19":"և ասաց. «Ի՛նձ էլ այս իշխանությունը տվեք, որպեսզի ում վրա ձեռքս դնեմ, Սուրբ Հոգին ստանա»։","20":"Պետրոսը նրան ասաց. «Կորի՛ր քո արծաթի հետ միասին, որովհետև կարծեցիր, թե Աստծու պարգևը կարելի է փողով առնել։","21":"Դու դրանում ո՛չ մաս ունես, ո՛չ ժառանգություն, որովհետև քո սիրտն Աստծու առաջ ուղիղ չէ։","22":"Արդ քո այդ չարության համար ապաշխարի՛ր և աղաչի՛ր Տիրոջը. թերևս քո սրտի չար խորհուրդը ներվի քեզ,","23":"որովհետև քեզ տեսնում եմ դառն մաղձի և անիրավության կապանքների մեջ»։","24":"Սիմոնն ասաց. «Դո՛ւք Տիրոջն ինձ համար աղոթեք, որպեսզի ինձ վրա ձեր ասածներից ոչինչ չգա»։","25":"Եվ նրանք, վկայություն տալով ու Տիրոջ խոսքը քարոզելով, վերադարձան Երուսաղեմ և սամարացիների շատ գյուղերում էին ավետարանում։","26":"Եվ Տիրոջ հրեշտակը Փիլիպպոսին ասաց. «Վե՛ր կաց և կեսօրին մոտ գնա՛ Երուսաղեմից Գազա իջնող ճանապարհով։ Այն անապատ է»։","27":"Նա վեր կացավ գնաց։ Ահա եթովպացի մի մարդ, որ ներքինի էր և Եթովպիայի Կանդակի թագուհու պաշտոնյաներից, որը նաև թագուհու գանձապահն էր, երկրպագության համար եկել էր Երուսաղեմ.","28":"վերադառնալիս իր կառքում նստած՝ Եսայի մարգարեի գիրքն էր կարդում։","29":"Հոգին Փիլիպպոսին ասաց. «Առաջացի՛ր և այդ կառքի՛ն մոտեցիր»։","30":"Փիլիպպոսն առաջ վազելով լսեց, որ Եսայու մարգարեությունից է կարդում, և հարցրեց. «Արդյոք հասկանո՞ւմ ես, թե ինչ ես կարդում»։","31":"Իսկ նա պատասխանեց. «Ինչպե՞ս կկարողանամ, եթե մեկն ինձ չուղղորդի»։ Նա խնդրեց Փիլիպպոսին, որ բարձրանա և նստի իր մոտ։","32":"Եվ սա էր գրքի այն հատվածը, որ կարդում էր. «Իբրև ոչխար մորթվելու տարվեց, և իբրև գառ, որ լուռ կանգնում է իրեն խուզողի առաջ, այդպես էլ նա իր բերանը չի բացում։","33":"Նրա խոնարհության պատճառով նրա իրավունքը մերժվեց. ո՞վ պիտի նրա ցեղի մասին պատմի, քանի որ նրա կյանքը երկրից վերցվեց» (Ես. 53.7-8)։","34":"Եվ ներքինին Փիլիպպոսին ասաց. «Խնդրում եմ քեզ, ո՞ւմ մասին է մարգարեն այս ասում՝ ի՞ր, թե՞ մեկ ուրիշի»։","35":"Փիլիպպոսը բաց արեց բերանը և սկսելով այս գրքից՝ նրան ավետարանեց Հիսուսի մասին։","36":"Ճանապարհով ընթանալիս մի ջրի մոտ հասան, և ներքինին ասաց. «Ահա ջուր. ի՞նչն է ինձ արգելում, որ մկրտվեմ»։","37":"Փիլիպպոսը նրան պատասխանեց. «Եթե ամբողջ սրտով հավատում ես, կարող ես մկրտվել»։ Նա ասաց. «Հավատում եմ, որ Հիսուս Քրիստոսն Աստծու Որդին է»։","38":"Եվ հրամայեց կառքը կանգնեցնել. Փիլիպպոսն ու ներքինին իջան ջուրը, և նա մկրտեց ներքինուն։","39":"Երբ ջրից դուրս եկան, Տիրոջ Հոգին Փիլիպպոսին հափշտակեց տարավ, ու ներքինին այլևս չտեսավ նրան. և նա ուրախությամբ գնաց իր ճանապարհով։","40":"Փիլիպպոսը հայտնվեց Ազովտոսում և շրջելով ավետարանում էր բոլոր քաղաքներում, մինչև որ եկավ Կեսարիա։"},"9":{"1":"Իսկ Սողոսը, որ Տիրոջ աշակերտներին սպառնալով ու նրանց սպանելով էր տակավին ներշնչված, եկավ քահանայապետի մոտ՝","2":"նրանից Դամասկոսի ժողովարաններին ուղղված նամակներ խնդրելու, ինչպես նաև եթե ճանապարհին գտնի Խոսքին հետևող որևէ մեկին՝ տղամարդ թե կին, կապված Երուսաղեմ բերի։","3":"Ճանապարհին, երբ նա մոտենում էր Դամասկոսին, հանկարծ նրա շուրջը երկնքից մի լույս փայլատակեց։","4":"Գետնին ընկնելով՝ նա մի ձայն լսեց, որ իրեն ասում էր. «Սավո՛ւղ, Սավո՛ւղ, ինչո՞ւ ես ինձ հալածում»։","5":"Նա ասաց. «Ո՞վ ես, Տե՛ր»։ Ասաց. «Ես Հիսուսն եմ, որին դու հալածում ես։","6":"Վե՛ր կաց, մտի՛ր քաղաք, և քեզ կասվի, թե դու ի՛նչ պետք է անես»։","7":"Իսկ նրան ուղեկցող մարդիկ պապանձված կանգնել էին. ձայնը լսում էին, սակայն ոչինչ չէին տեսնում։","8":"Սողոսը գետնից վեր կացավ, բայց աչքերը բացելով՝ ոչինչ չէր տեսնում։ Նրան ձեռքից բռնած մտցրին Դամասկոս։","9":"Երեք օր չէր տեսնում. ո՛չ կերավ, ո՛չ էլ խմեց։","10":"Դամասկոսում Անանիա անունով մի աշակերտ կար։ Տերը տեսիլքի մեջ նրան ասաց. «Անա՛նիա»։ Նա ասաց. «Ահա այստեղ եմ, Տե՛ր»։","11":"Եվ Տերը նրան ասաց. «Վեր կաց գնա՛ այն փողոցով, որ \"Ուղիղ\" է կոչվում, և Հուդայի տանը փնտրի՛ր Սողոս անունով մի տարսոնացու. նա այնտեղ աղոթում է»։","12":"Սողոսն էլ տեսիլքի մեջ Անանիա անունով մի մարդու տեսավ, որ մտավ և ձեռքն իր վրա դրեց, որպեսզի տեսողությունը վերստանա։","13":"Անանիան պատասխանեց. «Տե՛ր, ես շատերից լսեցի այդ մարդու մասին, թե որքա՛ն չարիքներ է արել քո սրբերին Երուսաղեմում։","14":"Եվ նա այստեղ էլ քահանայապետներից իշխանություն ունի ձերբակալելու բոլոր նրանց, ովքեր քո անվանն են կոչ անում»։","15":"Տերը նրան ասաց. «Գնա՛, որովհետև նա ինձ համար ընտրյալ անոթ է՝ հեթանոս ազգերի և թագավորների, Իսրայելի որդիների առաջ իմ անունը հայտնելու։","16":"Ես նրան ցույց կտամ, թե որքա՛ն պետք է չարչարվի իմ անվան համար»։","17":"Անանիան գնաց, այն տունը մտավ, ձեռքը դրեց նրա վրա և ասաց. «Սավո՛ւղ եղբայր, Տե՛րն ինձ ուղարկեց՝ Հիսուսը, որը քեզ ճանապարհին երևաց, որպեսզի տեսողությունդ վերստանաս և Սուրբ Հոգով լցվես»։","18":"Եվ իսկույն նրա աչքերից կեղևի պես բաներ թափվեցին։ Նա վերստին տեսավ և ոտքի ելավ մկրտվելու։","19":"Եվ սնունդ ընդունելով՝ զորացավ։ Սողոսը մի քանի օր Դամասկոսում գտնվող աշակերտների հետ անցկացրեց։","20":"Նա անմիջապես ժողովարաններում քարոզեց Հիսուսին, որ նա է Աստծու Որդին։","21":"Բոլորը, ովքեր լսում էին, զարմանում էին և ասում. «Սա չէ՞ր, որ հալածում էր Երուսաղեմում դրա անվանը կոչ անողներին, և այստեղ էլ նրա համար է եկել, որ սրանց ձերբակալելով՝ քահանայապետների մոտ տանի»։","22":"Բայց Սողոսն է՛լ ավելի էր զորանում և շփոթեցնում Դամասկոսում բնակվող հրեաներին՝ ապացուցելով, որ սա է Քրիստոսը։","23":"Բազում օրեր անց հրեաները որոշեցին նրան սպանել։","24":"Բայց Սողոսին հայտնի դարձավ նրանց դավադրությունը։ Նրանք գիշերուզօր քաղաքի դռների մոտ էին, որպեսզի նրան սպանեին։","25":"Աշակերտները գիշերով նրան վերցրին ու պարսպից կախելով՝ զամբյուղով ցած իջեցրին։","26":"Երբ Սողոսը եկավ Երուսաղեմ, փորձում էր աշակերտներին հարել, սակայն բոլորը նրանից վախենում էին ու չէին հավատում, որ իսկապես աշակերտ է։","27":"Բայց Բառնաբասը նրան տարավ առաքյալների մոտ ու պատմեց, թե ինչպե՛ս է նա ճանապարհին Տիրոջը տեսել ու նրա հետ խոսել և թե ինչպե՛ս է Դամասկոսում համարձակ քարոզել Հիսուսի անունով։","28":"Սողոսը Երուսաղեմում նրանց հետ էր մտնում ու դուրս գալիս՝ համարձակ քարոզելով Հիսուսի անունով։","29":"Նա խոսում և վիճաբանում էր հունախոսների հետ, իսկ նրանք նախաձեռնում էին նրան սպանել։","30":"Սակայն եղբայրները, այդ իմանալով, նրան Կեսարիա իջեցրին և ուղարկեցին Տարսոն։","31":"Բայց եկեղեցին ամբողջ Հուդայում, Գալիլեայում և Սամարիայում խաղաղության մեջ էր. հիմնավորվելով և Տիրոջ երկյուղով ընթանալով՝ Սուրբ Հոգու մխիթարությամբ աճում էր։","32":"Եվ Պետրոսը, որ շրջում էր ամենուրեք, իջավ նաև այն սրբերի մոտ, որոնք Լյուդդայում էին ապրում։","33":"Այնտեղ գտավ Էնեան անունով մի մարդու, որն ութ տարի շարունակ պառկած էր մահճի մեջ։ Նա անդամալույծ էր։","34":"Պետրոսը նրան ասաց. «Էնեա՛ն, Հիսուս Քրիստոսը քեզ բժշկում է, վե՛ր կաց և անկողինդ հարդարի՛ր»։ Նա իսկույն վեր կացավ։","35":"Եվ նրան տեսան բոլորը, ովքեր ապրում էին Լյուդդայում և Սարովնայում, որոնք դեպի Տերը դարձան։","36":"Հոպպեում Տաբիթա (որ «Այծեմնիկ» է թարգմանվում) անունով մի կին կար, որ աշակերտ էր. նա բազում բարի գործեր ու ողորմություններ էր արել։","37":"Պատահեց, որ այդ օրերին նա հիվանդացավ ու մեռավ. նրան լվացին և վերնատանը դրեցին։","38":"Քանի որ Լյուդդան Հոպպեին մոտ էր, ապա երբ աշակերտները լսեցին, որ Պետրոսն այնտեղ է, նրա մոտ երկու մարդ ուղարկեցին՝ խնդրելով. «Մի՛ հապաղիր մեզ մոտ գալ»։","39":"Պետրոսը ելավ ու նրանց հետ գնաց։ Երբ եկավ, նրան վերնատուն բարձրացրին։ Բոլոր այրիները նրա շուրջը հավաքվեցին. լալիս էին և ցույց տալիս այն շապիկներն ու զգեստները, որ Այծեմնիկն էր պատրաստում, երբ դեռ իրենց հետ էր։","40":"Պետրոսը բոլորին դուրս հանեց, ծնկի իջավ, աղոթեց և դեպի աճյունը դառնալով՝ ասաց. «Տաբի՛թա, վե՛ր կաց»։ Նա աչքերը բացեց և Պետրոսին տեսնելով՝ ուղիղ նստեց։","41":"Պետրոսը ձեռքը նրան մեկնեց, ոտքի կանգնեցրեց, ապա կանչեց սրբերին ու այրիներին և նրանց առաջ կենդանի կանգնեցրեց նրան։","42":"Ամբողջ Հոպպեում դա հայտնի դարձավ, և շատերը հավատացին Տիրոջը։","43":"Նա բավականաչափ օրեր մնաց Հոպպեում՝ ոմն կաշեգործ Սիմոնի մոտ։"},"10":{"1":"Կեսարիայում Կոռնելիոս անունով մի մարդ կար՝ «Իտալական» կոչվող գնդի հարյուրապետ։","2":"Նա, բարեպաշտ ու աստվածավախ լինելով, իր ամբողջ ընտանիքի հետ ժողովրդին շատ ողորմություններ էր անում և ամեն ժամ աղոթում էր Աստծուն։","3":"Օրվա իններորդ ժամին մոտ նա տեսիլքի մեջ հայտնապես տեսավ Աստծու հրեշտակին, որը, մտնելով իր մոտ, ասաց. «Կոռնելիո՛ս»։","4":"Իսկ նա, հրեշտակին նայելով, զարհուրեց ու ասաց. «Ի՞նչ է, Տե՛ր»։ Նա ասաց նրան. «Քո աղոթքներն ու քո ողորմություններն Աստծու առաջ բարձրացան՝ քո մասին հիշեցնելու համար։","5":"Հիմա մա՛րդ ուղարկիր Հոպպե ու կանչի՛ր ոմն Սիմոնի, որ Պետրոս է կոչվում։","6":"Նա հյուրընկալվել է ոմն կաշեգործ Սիմոնի մոտ, որի տունը ծովեզերքին է»։","7":"Երբ իր հետ խոսող հրեշտակը գնաց, նա կանչեց ծառաներից երկուսին և մի բարեպաշտ զինվորի, որն իր ծառայողներից էր։","8":"Եվ նրանց ամեն ինչ պատմելով՝ ուղարկեց Հոպպե։","9":"Հաջորդ օրը, երբ նրանք ճանապարհին էին ու մոտենում էին քաղաքին, Պետրոսը վեցերորդ ժամին մոտ բարձրացավ տանիք՝ աղոթելու։","10":"Նա քաղց զգաց և ուտել էր ուզում։ Մինչ ճաշ էին պատրաստում, նա հափշտակության մեջ ընկավ։","11":"Տեսավ երկինքը բացված ու մեծ սփռոցի պես մի բան՝ չորս ծայրից վերևից կախված, երկրի վրա իջնելիս։","12":"Դրա մեջ կային երկրի բոլոր չորքոտանիները, սողունները և երկնքի թռչունները։","13":"Եվ մի ձայն ասաց նրան. «Վե՛ր կաց, Պետրո՛ս, մորթի՛ր ու կե՛ր»։","14":"Պետրոսն ասաց. «Քա՛վ լիցի, Տե՛ր, որովհետև ես երբեք պիղծ և անմաքուր բան չեմ կերել»։","15":"Երկրորդ անգամ ձայնը դարձյալ ասաց նրան. «Ինչ որ Աստված մաքուր դարձրեց, դու պիղծ մի՛ համարիր»։","16":"Դա եղավ երեք անգամ, և սփռոցն իսկույն երկինք բարձրացավ։","17":"Մինչ Պետրոսը մտքում զարմանում էր, թե իր տեսած տեսիլքն ի՛նչ էր, ահա Կոռնելիոսի ուղարկած մարդիկ, Սիմոնի տան տեղը հարցնելով, կանգնեցին դռան մոտ։","18":"Նրանք ձայն տվեցին ու հարցնում էին, թե Սիմոնը, որ Պետրոս է կոչվում, այդտե՞ղ է հյուրընկալվել։","19":"Մինչ Պետրոսը մտորում էր տեսիլքի մասին, Հոգին նրան ասաց. «Ահա երեք մարդ քեզ են փնտրում։","20":"Վե՛ր կաց, իջի՛ր և առանց վարանելու գնա՛ նրանց հետ, որովհետև ես եմ ուղարկել նրանց»։","21":"Պետրոսն այդ մարդկանց մոտ իջավ ու ասաց. «Ահա ես եմ, ում փնտրում եք։ Ինչի՞ համար եք եկել»։","22":"Նրանք ասացին. «Կոռնելիոս հարյուրապետը՝ արդար և աստվածավախ մի մարդ, որ հարգված է բոլոր հրեաներից, սուրբ հրեշտակից հրաման ստացավ, որ քեզ իր տուն կանչի ու քեզանից խոսք լսի»։","23":"Եվ նրանց ներս կանչելով՝ հյուրընկալեց։ Հաջորդ օրը Պետրոսը գնաց նրանց հետ. Հոպպեում գտնվող եղբայրներից ոմանք ևս գնացին նրա հետ։","24":"Հաջորդ օրը մտան Կեսարիա։ Կոռնելիոսը սպասում էր նրանց՝ կանչելով նաև իր ազգականներին ու մտերիմ բարեկամներին։","25":"Հենց Պետրոսը ներս մտավ, Կոռնելիոսը նրան ընդառաջ ելավ ու ոտքերն ընկնելով երկրպագեց։","26":"Պետրոսը նրան ոտքի կանգնեցրեց ու ասաց. «Վե՛ր կաց, ես ինքս էլ մարդ եմ»։","27":"Եվ նրա հետ խոսելով ներս մտավ ու այնտեղ հավաքված բազում մարդկանց գտավ։","28":"Պետրոսը նրանց ասաց. «Դուք գիտեք, որ հրեա մարդուն օրինավոր չէ օտարազգի որևէ մեկին դիպչելը կամ մոտենալը. բայց Աստված ինձ պատվիրեց ոչ մի մարդու պիղծ կամ անմաքուր չհամարել։","29":"Դրա համար էլ առանց առարկության եկա, երբ կանչվեցի։ Հիմա հարցնում եմ. \"Ինչո՞ւ եք ինձ կանչել\"»։","30":"Կոռնելիոսն ասաց. «Չորս օր առաջ հենց այս ժամին՝ մինչև իններորդ ժամը, իմ տանն աղոթք էի անում։ Ահա իմ առաջ մի մարդ կանգնեց՝ փայլուն զգեստներով,","31":"և ասաց. \"Կոռնելիո՛ս, քո աղոթքը լսվեց, ու քո ողորմություններն Աստծու առաջ հիշվեցին։","32":"Արդ, մա՛րդ ուղարկիր Հոպպե ու կանչի՛ր Սիմոնին, որ Պետրոս է կոչվում. նա հյուրընկալվել է ոմն կաշեգործ Սիմոնի տանը՝ ծովեզերքին\"։","33":"Ես էլ իսկույն մարդ ուղարկեցի քեզ մոտ։ Դու լավ արեցիր, որ եկար։ Այժմ մենք բոլորս կանգնած ենք Աստծու առաջ, որպեսզի լսենք այն ամենը, ինչ Տիրոջ կողմից հրամայված է քեզ»։","34":"Պետրոսը բացեց բերանն ու ասաց. «Իրապես հասկանում եմ, որ Աստված աչառու չէ,","35":"այլ բոլոր ազգերի մեջ ով երկյուղում է նրանից ու արդարություն գործում, ընդունելի է նրան։","36":"Նա իր խոսքն ուղարկեց Իսրայելի որդիներին՝ քարոզելով Հիսուս Քրիստոսի միջոցով խաղաղությունը։ Նա է բոլորի Տերը։","37":"Դուք ինքներդ գիտեք այն եղելությունը, որ պատահեց ամբողջ Հրեաստանում։ Այն սկսվեց Գալիլեայից, Հովհաննեսի քարոզած մկրտությունից հետո։","38":"Գիտեք Հիսուսին, որ Նազարեթից էր. թե ինչպե՛ս Աստված նրան օծեց Սուրբ Հոգով ու զորությամբ. որը շրջում էր՝ բարիք գործելով ու սատանայից բռնված բոլորին բժշկելով, որովհետև Աստված նրա հետ էր։","39":"Եվ մենք վկա ենք այն ամենին, ինչ նա արեց հրեաների երկրում և Երուսաղեմում, որին սպանեցին՝ փայտից կախելով։","40":"Նրան Աստված երրորդ օրը հարություն տվեց, ու հայտնվեց","41":"ոչ թե ամբողջ ժողովրդին, այլ մեզ՝ Աստծուց նախասահմանվածներիս, որ նրա հետ կերանք ու խմեցինք մեռելներից նրա հարություն առնելուց հետո։","42":"Նա մեզ պատվիրեց քարոզել ժողովրդին ու վկայություն տալ, որ ինքն է Աստծուց սահմանված դատավորը մեռածների ու կենդանիների։","43":"Բոլոր մարգարեները նրա մասին վկայում են, որ բոլոր նրան հավատացողները նրա անունով մեղքերի թողություն կստանան»։","44":"Մինչ Պետրոսն այս բաներն էր ասում, Սուրբ Հոգին իջավ բոլոր այս խոսքը լսողների վրա։","45":"Եվ Պետրոսի հետ եկած հավատացյալները, որ թլփատվածներից էին, զարմացան, որ Սուրբ Հոգու պարգևը հեթանոսների մեջ էլ է հեղվում.","46":"որովհետև լսում էին, որ նրանք տարբեր լեզուներով էին խոսում և Աստծուն փառաբանում։","47":"Այդ ժամանակ Պետրոսն ասաց. «Ո՞վ կարող է արգելել, որ սրանք մկրտվեն ջրով, որոնք ընդունեցին Սուրբ Հոգին, ինչպես և մենք»։","48":"Եվ հրամայեց նրանց, որ մկրտվեն Հիսուս Քրիստոսի անունով։ Այդ ժամանակ խնդրեցին նրան, որ մի քանի օր ևս մնա։"},"11":{"1":"Առաքյալները և Հրեաստանում գտնվող եղբայրները լսեցին, որ հեթանոսները ևս ընդունել են Աստծու խոսքը։","2":"Երբ Պետրոսը Երուսաղեմ բարձրացավ, թլփատվածները մեղադրում էին նրան՝","3":"ասելով. «Դու անթլփատ մարդկանց մոտ մտար ու նրանց հետ կերար»։","4":"Պետրոսը սկսեց հերթականությամբ պատմել նրանց ու ասաց.","5":"«Ես Հոպպե քաղաքում աղոթում էի և հափշտակության մեջ ընկնելով՝ տեսիլք տեսա. վերևից չորս ծայրը կախված սփռոցի պես մի բան էր իջնում երկնքից ու հասավ մինչև ինձ։","6":"Մինչ դրան էի նայում, տեսա երկրի չորքոտանիներին, գազաններին, սողուններին ու երկնքի թռչուններին։","7":"Եվ լսեցի մի ձայն, որ ասում էր ինձ. \"Վե՛ր կաց, Պետրո՛ս, մորթի՛ր և կե՛ր\"։","8":"Բայց ես ասացի. \"Քա՛վ լիցի, Տե՛ր, որովհետև իմ բերանը երբեք պիղծ և անմաքուր բան չի մտել\"։","9":"Եվ ձայնն ինձ երկրորդ անգամ երկնքից պատասխանեց. \"Այն, ինչ Աստված մաքուր դարձրեց, դու պիղծ մի՛ համարիր\"։","10":"Սա պատահեց երեք անգամ, և ամեն ինչ դարձյալ երկինք բարձրացավ։","11":"Եվ ահա այդ պահին երեք մարդ, որ ուղարկվել էին ինձ մոտ Կեսարիայից, եկան, կանգնեցին այն տան առաջ, որտեղ ես գտնվում էի։","12":"Եվ Հոգին ինձ ասաց, որ առանց վարանելու գնամ նրանց հետ։ Այս վեց եղբայրներն էլ ինձ հետ եկան, և մտանք այն մարդու տունը։","13":"Նա մեզ պատմեց, թե ինչպես է իր տանը տեսել հրեշտակին, որ կանգնել ու ասում էր. \"Մա՛րդ ուղարկիր Հոպպե և Պետրոս կոչված Սիմոնին կանչի՛ր։","14":"Նա քեզ խոսքեր կասի, որոնցով կփրկվեք դու և քո ամբողջ տունը\"։","15":"Երբ սկսեցի խոսել, Սուրբ Հոգին իջավ նրանց վրա, ինչպես որ իջել էր մեզ վրա սկզբում։","16":"Այդ ժամանակ ես հիշեցի Տիրոջ այն խոսքը, որ ասում էր. \"Հովհաննեսը մկրտեց ջրով, բայց դուք կմկրտվեք Սուրբ Հոգով\"։","17":"Ուրեմն եթե Աստված միևնույն պարգևը տվեց նրանց, ինչպես և մեզ, երբ Տեր Հիսուս Քրիստոսին հավատացինք, ապա ես ո՞վ էի, որ կարողանայի Աստծուն արգելք լինել»։","18":"Այս լսելով՝ լռեցին և փառաբանում էին Աստծուն՝ ասելով. «Ուրեմն Աստված հեթանոսներին ևս դեպի կյանք տանող ապաշխարություն տվեց»։","19":"Նրանք, որ ցրվել էին Ստեփանոսի քարկոծումից հետո եղած հալածանքի պատճառով, հասան մինչև Փյունիկե, Կիպրոս ու Անտիոք։ Նրանք ոչ ոքի Աստծու խոսքը չէին քարոզում, բացի հրեաներից։","20":"Նրանցից ոմանք, որ կիպրացի և կյուրենացի էին, Անտիոք մտնելով դիմում էին հույներին՝ Տեր Հիսուսին ավետարանելով։","21":"Եվ Տիրոջ ձեռքը նրանց հետ էր, և բազմաթիվ մարդիկ հավատացին ու դեպի Տերը դարձան։","22":"Այս լուրը հասավ Երուսաղեմի եկեղեցու ականջին։ Եվ ուղարկեցին Բառնաբասին, որ գնա մինչև Անտիոք։","23":"Երբ նա եկավ ու տեսավ Աստծու շնորհը, ուրախացավ և բոլորին հորդորում էր, որ հոժար սրտով Տիրոջ հետ մնան։","24":"Քանի որ նա բարի, Սուրբ Հոգով ու հավատով լցված մարդ էր, բազում ժողովուրդ միացավ Տիրոջը հավատացողներին։","25":"Բառնաբասը գնաց Տարսոն՝ Սողոսին փնտրելու։","26":"Երբ նրան գտավ, բերեց Անտիոք։ Նրանք մի ամբողջ տարի հավաքվում էին եկեղեցում և բավականաչափ մարդկանց ուսուցանում։ Աշակերտներն առաջին անգամ Անտիոքում «քրիստոնյա» անվանվեցին։","27":"Այդ օրերին Երուսաղեմից մարգարեներ իջան Անտիոք։","28":"Նրանցից Ագաբոս անունով մեկը վեր կացավ և Հոգու միջոցով կանխասաց, որ ամբողջ աշխարհում մեծ սով է լինելու, որը և Կլավդիոս կայսեր ժամանակ եղավ։","29":"Եվ աշակերտները որոշեցին, որ յուրաքանչյուրն ըստ իր կարողության օգնություն ուղարկի Հրեաստանում ապրող եղբայրներին,","30":"որը և արեցին՝ Բառնաբասի ու Սողոսի միջոցով երեցներին ուղարկելով։"},"12":{"1":"Այդ ժամանակ Հերովդես թագավորը ձեռնամուխ եղավ եկեղեցուց ոմանց չարչարելու գործին։","2":"Եվ սրով սպանեց Հակոբոսին՝ Հովհաննեսի եղբորը։","3":"Տեսնելով, որ դա հաճելի է հրեաներին, Բաղարջակերաց տոնի օրերին Պետրոսին էլ ձերբակալել տվեց։","4":"Թագավորը բռնեց նրան և բանտ դրեց՝ հանձնելով քառակազմ զինվորների չորս հերթափոխի հսկողությանը։ Նա կամենում էր Զատկից հետո նրան ժողովրդի առաջ հանել։","5":"Պետրոսը պահվում էր բանտում, բայց եկեղեցին նրա համար անդադար աղոթում էր Աստծուն։","6":"Երբ Հերովդեսն ուզեց նրան դուրս բերել, այդ գիշեր Պետրոսը, կրկնակի շղթաներով կապված, քնած էր երկու զինվորների միջև, իսկ պահակները դռան առաջ պահպանում էին բանտը։","7":"Եվ ահա Տիրոջ հրեշտակը եկավ, և բանտախցում լույս ծագեց։ Նա հրեց Պետրոսի կողին, արթնացրեց նրան ու ասաց. «Շո՛ւտ, վե՛ր կաց»։ Եվ շղթաներն ընկան նրա ձեռքերից։","8":"Հրեշտակն ասաց նրան. «Գոտիդ կապի՛ր և հողաթափերդ հագի՛ր»։ Նա այդպես էլ արեց։ Եվ ասաց նրան. «Զգեստդ վրա՛դ գցիր ու ի՛նձ հետևիր»։","9":"Դուրս ելնելով՝ նա գնում էր նրա հետևից ու չգիտեր, որ հրեշտակի կողմից կատարվածը իրական էր, որովհետև կարծում էր, թե տեսիլք է տեսնում։","10":"Երբ նրանք անցան առաջին և երկրորդ պահապաններից, հասան մինչև երկաթյա դուռը, որ դեպի քաղաք էր տանում։ Այն ինքնիրեն բացվեց նրանց առաջ։ Նրանք դուրս ելան և մի փողոց անցան, և հրեշտակն իսկույն հեռացավ նրանից։","11":"Երբ Պետրոսն ուշքի եկավ, ասաց. «Այժմ իրապես գիտեմ, որ Տերն իր հրեշտակին ուղարկեց և ինձ փրկեց Հերովդեսի ձեռքից ու այն ամենից, ինչ սպասվում էր հրեա ժողովրդից»։","12":"Եվ սթափվելով՝ եկավ «Մարկոս» կոչված Հովհաննեսի մոր՝ Մարիամի տուն, որտեղ շատերը հավաքվել և աղոթում էին։","13":"Բախեց դրսի դուռը. Ռոդի անունով մի աղախին մոտեցավ լսելու։","14":"Նա ճանաչեց Պետրոսի ձայնը և ուրախությունից դուռը չբացեց, այլ ներս վազեց ու պատմեց, որ Պետրոսը դռանը կանգնած է։","15":"Նրանք ասացին նրան. «Խելագարվել ես»։ Իսկ նա պնդում էր, որ այդպես է։ Նրանք էլ ասում էին. «Նրա հրեշտակն է»։","16":"Պետրոսը շարունակում էր դուռը բախել. երբ բացեցին, տեսան նրան ու զարմացան։","17":"Նա ձեռքով նշան արեց նրանց, որ լուռ մնան, և պատմեց, թե ինչպե՛ս Տերն իրեն բանտից հանեց։ Եվ ասաց. «Սրա մասին հայտնե՛ք Հակոբոսին ու եղբայրներին»։ Ապա դուրս ելավ և ուրիշ տեղ գնաց։","18":"Երբ առավոտ եղավ, զինվորների մեջ մեծ իրարանցում էր, թե Պետրոսն ի՛նչ եղավ։","19":"Երբ Հերովդեսը նրան փնտրեց ու չգտավ, պահակներին քննելուց հետո հրամայեց սպանել։ Պետրոսը Հրեաստանից իջավ Կեսարիա ու այնտեղ էր մնում։","20":"Հերովդեսը Տյուրոսի և Սիդովնի բնակիչների հետ պայքարի մեջ էր։ Նրանք միաբանված ներկայացան նրան և համոզելով Բլաստոսին՝ արքունի սենեկապետին, խաղաղություն էին խնդրում, որովհետև իրենց երկիրն արքունիքից էր կերակրվում։","21":"Որոշված օրը Հերովդեսը, թագավորական զգեստ հագած, նստել էր ատյանում և հրապարակավ խոսում էր նրանց հետ։","22":"Իսկ ամբոխն աղաղակում էր. «Դա Աստծու ձայնն է և ոչ թե մարդու»։","23":"Եվ Տիրոջ հրեշտակն իսկույն հարվածեց նրան, որովհետև Աստծո՛ւն չտվեց փառքը, և որդերով լցվեց ու մեռավ։","24":"Իսկ Աստծու խոսքն աճում էր ու բազմանում։","25":"Բառնաբասն ու Սողոսը ծառայությունը կատարելուց հետո վերադարձան Երուսաղեմ՝ իրենց հետ վերցնելով նաև Հովհաննեսին, որ Մարկոս էր կոչվում։"},"13":{"1":"Անտիոքի եկեղեցում կային մի քանի մարգարեներ և ուսուցիչներ՝ Բառնաբասն ու Շմավոնը, որ Նիգեր էր կոչվում, Ղուկիոս Կյուրենացին, Մանայենը՝ Հերովդես չորրորդապետի ընկերը, և Սողոսը։","2":"Երբ նրանք Տիրոջը պաշտամունք էին մատուցում և ծոմ էին պահում, Սուրբ Հոգին ասաց. «Առանձնացրե՛ք ինձ համար Բառնաբասին ու Սողոսին այն գործի համար, որին ես կանչել եմ նրանց»։","3":"Այդ ժամանակ ծոմ պահելով ու աղոթելով՝ նրանց վրա ձեռք դրեցին և ուղարկեցին։","4":"Նրանք, Սուրբ Հոգուց ուղարկված, Սելևկիա իջան և այնտեղից նավարկեցին դեպի Կիպրոս։","5":"Սաղամինա հասնելով՝ հրեաների ժողովարաններում Աստծու խոսքն էին քարոզում. Հովհաննեսը նրանց օգնականն էր։","6":"Շրջելով ամբողջ կղզին մինչև Պափոս՝ գտան մի մոգի՝ Բարիհեսու անունով հրեա սուտ մարգարեին։","7":"Նա ընկերն էր հյուպատոս Սերգիոս Պողոսի, որն իմաստուն մարդ էր։ Սերգիոսը, Բառնաբասին ու Սողոսին իր մոտ կանչելով, ուզում էր լսել Աստծու խոսքը։","8":"Բայց Եղիմաս մոգը (որովհետև նրա անունն այսպես է թարգմանվում) նրանց դեմ կանգնեց՝ ցանկանալով հավատից շեղել հյուպատոսին։","9":"Սակայն Սողոսը, որ Պողոսն է, Սուրբ Հոգով լցված, նայեց նրան","10":"և ասաց. «Ո՛վ դու, ամեն նենգությամբ ու խորամանկությամբ լցված սատանայի՛ որդի, թշնամի՛ ամեն արդարության, չե՞ս դադարելու Տիրոջ ուղիղ ճանապարհները շեղելուց։","11":"Այժմ ահա Տիրոջ ձեռքը քեզ վրա է, և կույր կլինես ու միառժամանակ արև չես տեսնի»։ Եվ իսկույն նրա վրա մեգ ու խավար իջավ, և խարխափելով առաջնորդողներ էր փնտրում։","12":"Այդ ժամանակ, երբ հյուպատոսը պատահածը տեսավ, հավատաց՝ Տիրոջ վարդապետության վրա զարմանալով։","13":"Եվ Պողոսն ու ուղեկիցները Պափոսից դուրս ելան, եկան Պամփյուլիայի Պերգե քաղաքը։ Իսկ Հովհաննեսը, նրանցից բաժանվելով, վերադարձավ Երուսաղեմ։","14":"Նրանք Պերգեից անցան, եկան Պիսիդիայի Անտիոք քաղաքը և շաբաթ օրը ժողովարան մտնելով՝ նստեցին։","15":"Օրենքի ու մարգարեների ընթերցումից հետո ժողովրդապետները նրանց մոտ մարդ ուղարկեցին ու ասացին. «Եղբայրնե՛ր, եթե դուք ժողովրդի համար մխիթարանքի խոսքեր ունեք, խոսե՛ք»։","16":"Պողոսը վեր կացավ, ձեռքով նշան արեց ու ասաց. «Ո՛վ իսրայելացիներ և դո՛ւք, որ երկնչում եք Աստծուց, լսե՛ք.","17":"այս ժողովրդի՝ Իսրայելի Աստվածն ընտրեց մեր հայրերին և Եգիպտոսի երկրում պանդխտության ժամանակ բարձրացրեց ժողովրդին ու հզոր բազկով նրանց այնտեղից դուրս բերեց։","18":"Շուրջ քառասուն տարի անապատում կերակրեց նրանց։","19":"Քանանի երկրում յոթ ազգերի ոչնչացնելով՝ նրանց երկիրը որպես ժառանգություն տվեց նրանց","20":"շուրջ չորս հարյուր հիսուն տարի։ Հետո նրանց դատավորներ տվեց՝ մինչև Սամուել մարգարեն։","21":"Այնուհետև թագավոր խնդրեցին, և Աստված նրանց տվեց Կիսի որդի Սավուղին՝ Բենիամինի ցեղից, որ թագավորեց քառասուն տարի։","22":"Ապա նրան փոխելով՝ թագավոր կարգեց Դավթին և նրա մասին վկայելով՝ ասաց. \"Գտա Հեսսեի որդի Դավթին՝ իմ սրտով մարդու, որը պիտի կատարի իմ ամբողջ կամքը\" (Սաղ. 89.20)։","23":"Աստված իր խոստման համաձայն սրա սերնդից իսրայելացիների համար տվեց Հիսուս Փրկչին։","24":"Նրա գալուստից առաջ Հովհաննեսն Իսրայելի ողջ ժողովրդին կանխավ քարոզել էր ապաշխարության մկրտությունը։","25":"Երբ Հովհաննեսն ավարտեց իր գործը, ասաց. \"Իմ մասին ի՞նչ եք կարծում. ո՞վ եմ։ Ես նա չեմ, բայց ահա ինձանից հետո գալիս է նա, որի ոտքերի կոշիկն արձակելու արժանի չեմ\"։","26":"Եղբայրնե՛ր, Աբրահամի տոհմի զավակնե՛ր և ձեր մեջ նրանք, ովքեր աստվածավախ են, ձե՛զ ուղարկվեց փրկության այս խոսքը։","27":"Որովհետև Երուսաղեմում ապրողները և նրանց իշխանավորները չճանաչեցին Հիսուսին, և նրան դատապարտելով՝ իրականացան մարգարեների խոսքերը, որոնք ընթերցվում են ամեն շաբաթ օրերին։","28":"Նրան մահապատժի ենթարկելու ոչ մի պատճառ չգտնելով՝ Պիղատոսից խնդրեցին նրան սպանել։","29":"Երբ նրա մասին գրված ամեն բան կատարեցին, փայտից իջեցրին ու գերեզման դրեցին։","30":"Բայց Աստված մեռելներից հարություն տվեց նրան,","31":"և նա բազում օրեր հայտնվեց նրանց, ովքեր նրա հետ Գալիլեայից Երուսաղեմ էին բարձրացել և ովքեր այժմ ժողովրդի առաջ նրա վկաներն են։","32":"Եվ մենք ձեզ ավետարանում ենք հայրերին տրված խոստումը,","33":"քանի որ Աստված այն իրագործեց մեր մեջ, որ նրանց որդիներն ենք, Հիսուսին հարություն տալով, ինչպես գրված է երկրորդ սաղմոսում. \"Դու իմ Որդին ես, ես այսօր ծնեցի քեզ\" (Սաղ. 2.7)։","34":"Եվ որ մեռելներից նրան հարություն տվեց ու այլևս ապականության չի դառնալու, այսպես ասաց. \"Ձեզ պիտի տամ այն սրբությունները, որ խոստացա Դավթին\" (Ես. 55.3)։","35":"Ուստի և մի ուրիշ տեղում ասում է. \"Քո Սրբին ապականություն տեսնել չես տա\" (Սաղ. 16.10)։","36":"Բայց Դավիթն իր սերնդի ժամանակ ծառայեց և Աստծու կամքով վախճանվեց և իր հայրերին միացավ, ապականություն տեսավ։","37":"Բայց նա, որին Աստված հարություն տվեց, ապականություն չտեսավ։","38":"Արդ, եղբայրնե՛ր, թող ձեզ հայտնի լինի, որ նրանով է ձեզ մեղքերի թողություն ավետարանվում։ Եվ այն ամենից, որ Մովսեսի օրենքով չկարողացաք արդարանալ,","39":"նրանով ամեն հավատացող կարդարանա։","40":"Արդ, զգո՛ւյշ եղեք, որ ձեզ վրա չգա մարգարեների կողմից ասվածը.","41":"\"Տեսե՛ք, արհամարհողնե՛ր, և զարմացե՛ք ու չքվե՛ք, որովհետև ես ձեր օրերում մի գործ եմ անելու, մի գործ, որին չպիտի հավատաք, եթե մեկը պատմի ձեզ\" (Ամբ. 1.5)»։","42":"Երբ այնտեղից դուրս ելան, խնդրում էին, որ հաջորդ շաբաթ ևս այդ մասին խոսեն։","43":"Երբ ժողովուրդը ցրվեց, հրեաներից ու բարեպաշտ նորադարձներից շատերը գնում էին Պողոսի ու Բառնաբասի հետևից, որոնք, նրանց հետ խոսելով, համոզում էին նրանց, որ շարունակեն Աստծու շնորհի մեջ մնալ։","44":"Հաջորդ շաբաթ օրը գրեթե ամբողջ քաղաքը հավաքվեց Աստծու խոսքը լսելու։","45":"Երբ հրեաները ժողովրդի բազմությունը տեսան, նախանձով լցվեցին և Պողոսի ասածներին հակաճառելով՝ հայհոյում էին։","46":"Իսկ Պողոսն ու Բառնաբասը համարձակորեն ասում էին. «Նախ ձե՛զ պետք է Աստծու խոսքը խոսվեր, բայց քանի որ դուք այն մերժում եք ու ձեզ արժանի չեք համարում հավիտենական կյանքին, ահա մենք դառնում ենք դեպի հեթանոսները։","47":"Որովհետև այսպես է մեզ պատվիրել Տերը. \"Քե՛զ դրեցի որպես լույս հեթանոսների, որպեսզի դու փրկություն բերես մինչև երկրի ծայրերը\" (Ես. 49.6, հմմտ. 42.6)»։","48":"Հեթանոսները, այս լսելով, ուրախանում էին և Տիրոջ խոսքը փառաբանում։ Եվ հավատացին նրանք, ովքեր սահմանված էին հավիտենական կյանքի համար։","49":"Տիրոջ խոսքը տարածվում էր ամբողջ գավառով։","50":"Բայց հրեաները գրգռեցին պատվավոր, երևելի կանանց ու քաղաքի գլխավորներին և Պողոսի ու Բառնաբասի դեմ հալածանք հարուցեցին և նրանց դուրս հանեցին իրենց սահմաններից։","51":"Իսկ նրանք, իրենց ոտքերի փոշին նրանց վրա թափ տալով, գնացին Իկոնիոն։","52":"Իսկ աշակերտները լցված էին ուրախությամբ և Սուրբ Հոգով։"},"14":{"1":"Իկոնիոնում նրանք նույնպես միասին էին մտնում հրեաների ժողովարան և խոսում այնպես, որ հրեաների և հույների մի մեծ բազմություն հավատաց։","2":"Բայց չհավատացող հրեաները հեթանոսների մտքերը գրգռեցին ու նրանց հոգիները եղբայրների դեմ չարացրին։","3":"Նրանք բավական ժամանակ մնացին այնտեղ՝ համարձակ խոսելով Տիրոջ մասին, որ հաստատում էր իր փրկարար շնորհը՝ նրանց ձեռքով նշաններ ու հրաշքներ կատարելով։","4":"Եվ քաղաքի բնակիչների մեջ երկպառակություն առաջացավ. ոմանք հրեաների կողմն էին, ոմանք՝ առաքյալների։","5":"Երբ հեթանոսներն ու հրեաներն իրենց իշխանավորների հետ նրանց չարչարելու և քարկոծելու դիմեցին,","6":"նրանք, տեղեկացվելով, փախան լիկայոնացիների Լյուստրա և Դերբե քաղաքներն ու շրջակա գավառը։","7":"Եվ այնտեղ ավետարանում էին։","8":"Լյուստրայում ոտքերից տկար մի մարդ կար նստած, որ ի ծնե կաղ էր ու երբեք չէր քայլել։","9":"Նա լսեց Պողոսի խոսքերը։ Պողոսը, նայելով նրան ու տեսնելով, որ փրկվելու հավատ ունի,","10":"բարձրաձայն ասաց. «Ոտքերիդ վրա ուղի՛ղ կանգնիր»։ Նա վեր ցատկեց և քայլում էր։","11":"Ժողովուրդը, տեսնելով այն, ինչ արեց Պողոսը, իր ձայնը բարձրացրեց ու լիկայոներեն ասաց. «Աստվածները մարդկանց կերպարանքով մեզ մոտ իջան»։","12":"Եվ Բառնաբասին Դիոս էին կոչում, իսկ Պողոսին՝ Հերմես, որովհետև նա էր խոսքի առաջնորդը։","13":"Իսկ Դիոսի քուրմը, որի տաճարը քաղաքից դուրս էր, ցուլեր և պսակներ բերելով քաղաքի դռների մոտ, ցանկանում էր բազմության հետ զոհ մատուցել։","14":"Երբ Բառնաբաս ու Պողոս առաքյալները լսեցին, իրենց զգեստները պատառոտելով՝ ամբոխի մեջ նետվեցին՝ աղաղակելով","15":"և ասելով. «Մարդի՛կ, այդ ի՞նչ եք անում. մենք էլ ձեզ նման մահկանացուներ ենք, որ ձեզ ավետարանում ենք, որպեսզի այդպիսի ունայնություններից դառնաք դեպի կենդանի Աստվածը, որը ստեղծեց երկինքն ու երկիրը, ծովն ու այն ամենը, ինչ կա նրանց մեջ.","16":"նա անցյալում բոլոր հեթանոս ազգերին թույլ տվեց, որ իրենց ճանապարհներով գնան։","17":"Թեև ինքն իրեն առանց վկայության չթողեց, այլ բարիք գործելով՝ երկնքից ձեզ անձրևներ ու պտղաբեր եղանակներ տվեց՝ լիացնելով կերակուրներով, և ձեր սրտերը՝ ուրախությամբ»։","18":"Եվ այս ասելով՝ ժողովրդին հազիվ հանդարտեցրին, որ իրենց զոհ չմատուցեն։","19":"Ապա Անտիոքից ու Իկոնիոնից հրեաներ եկան, ժողովրդին համոզեցին և Պողոսին քարկոծելով քաղաքից դուրս քաշեցին ու կարծում էին, թե մեռել է։","20":"Երբ աշակերտները շրջապատեցին նրան, վեր կացավ ու քաղաք մտավ։ Հաջորդ օրը նա Բառնաբասի հետ ելավ գնաց Դերբե։","21":"Այդ քաղաքում ևս ավետարանելուց և շատերին աշակերտ դարձնելուց հետո վերադարձան Լյուստրա, Իկոնիոն ու Անտիոք։","22":"Նրանք, աշակերտների սրտերն ամրացնելով, խնդրում էին, որ շարունակեն հավատի մեջ հաստատուն մնալ. «Մենք բազում նեղությունների միջով պետք է մտնենք Աստծու արքայություն»։","23":"Նրանց յուրաքանչյուր եկեղեցում երեցներ ձեռնադրեցին, աղոթեցին պահեցողությամբ ու նրանց հանձնեցին Տիրոջը, որին հավատացել էին։","24":"Այնուհետև շրջելով Պիսիդիայով՝ եկան Պամփյուլիա։","25":"Պերգեում Տիրոջ խոսքը քարոզելուց հետո իջան Ատալիա։","26":"Այնտեղից նավարկեցին դեպի Անտիոք, որտեղից տրվել էին Աստծու շնորհին իրենց կատարած գործի համար։","27":"Երբ նրանք եկան և հավաքեցին եկեղեցին, պատմեցին, թե Աստված իրենց հետ ինչե՛ր արեց և որ հեթանոսների համար հավատի դուռը բացեց։","28":"Եվ երկար ժամանակ աշակերտների հետ այնտեղ մնացին։"},"15":{"1":"Ոմանք, Հրեաստանից գալով, եղբայրներին ուսուցանում էին. «Եթե Մովսեսի օրենքի համաձայն չթլփատվեք, չեք կարող փրկվել»։","2":"Երբ Պողոսն ու Բառնաբասը նրանց հետ բավական հակառակություն ու վեճ ունեցան, որոշեցին, որ Պողոսն ու Բառնաբասը և նրանցից ոմանք այդ խնդրի համար բարձրանան Երուսաղեմ՝ առաքյալների և երեցների մոտ։","3":"Նրանք եկեղեցու կողմից ճանապարհ դրվեցին և Փյունիկեի ու Սամարիայի միջով անցնելով՝ պատմում էին հեթանոսների դարձի մասին և բոլոր եղբայրներին մեծ ուրախություն պատճառում։","4":"Երբ Երուսաղեմ հասան, ընդունվեցին եկեղեցու, առաքյալների և երեցների կողմից ու պատմեցին, թե Աստված ինչե՛ր արեց իրենց հետ։","5":"Փարիսեցիների աղանդից որոշ հավատացյալներ վեր կացան և ասացին. «Դրանց պետք է թլփատել ու պատվիրել, որ Մովսեսի օրենքը պահեն»։","6":"Եվ առաքյալներն ու երեցները հավաքվեցին այս հարցը քննելու։","7":"Երկար վիճաբանությունից հետո Պետրոսը վեր կացավ ու նրանց ասաց. «Եղբայրնե՛ր, դուք գիտեք, որ Աստծու ընտրությամբ է, որ առաջին օրերից ձեր միջից հեթանոսներն իմ բերանով Ավետարանի խոսքը լսեցին ու հավատացին։","8":"Եվ Աստված, որ գիտի մարդկանց սրտերը, նրանց վկայեց՝ Սուրբ Հոգին տալով նրանց այնպես, ինչպես մեզ։","9":"Եվ նրանց ու մեր միջև ոչ մի խտրություն չդրեց՝ հավատով նրանց սրտերը մաքրելով։","10":"Հիմա ինչո՞ւ եք փորձում Աստծուն՝ աշակերտների վզին դնելով մի լուծ, որ ո՛չ մեր հայրերը կարողացան տանել, ո՛չ էլ մենք։","11":"Բայց Տեր Հիսուսի շնորհով հավատում ենք, որ կփրկվենք, ինչպես և նրանք»։","12":"Եվ ողջ ժողովը լռեց. լսում էին Բառնաբասին ու Պողոսին, որոնք պատմում էին, թե Աստված հեթանոսների մեջ իրենց միջոցով որքա՛ն նշաններ ու հրաշքներ կատարեց։","13":"Եվ երբ նրանք լռեցին, Հակոբոսն ասաց. «Եղբայրնե՛ր, լսե՛ք ինձ։","14":"Շմավոնը պատմեց, թե ինչպե՛ս Աստված սկզբից ևեթ հոգացել էր, որ հեթանոսներից իր անունով մի ժողովուրդ ձևավորի։","15":"Դրան են համապատասխանում մարգարեների խոսքերը, ինչպես որ գրված է.","16":"\"Սրանից հետո կվերադառնամ ու Դավթի քանդված տունը կվերաշինեմ, նրա ավերակները կվերակառուցեմ և կվերականգնեմ այն,","17":"որպեսզի Տիրոջը փնտրեն մնացած մարդիկ և այն բոլոր հեթանոսները, որոնց վրա իմ անունն է դրված.","18":"ասում է Տերը, նա, որ անում է այս ամենը\" (Ամս. 9.11-12), և որի գործերը հայտնի են դարեր առաջ։","19":"Դրա համար ես կարծում եմ՝ չպետք է նեղել այն հեթանոսներին, որոնք դառնում են Աստծուն։","20":"Բայց թող նրանց ուղղված թուղթ գրվի, որ խորշեն կուռքերի պղծությունից, պոռնկությունից, խեղդամահ արված կենդանու մսից ու արյունից։","21":"Որովհետև Մովսեսի օրենքը, առաջին սերունդներից սկսած, յուրաքանչյուր քաղաքում իր քարոզիչներն ունի և ժողովարաններում ամեն շաբաթ օր ընթերցվում է»։","22":"Այդ ժամանակ առաքյալներին ու երեցներին ամբողջ եկեղեցու հետ միասին հաճելի թվաց իրենց միջից ընտրված մարդկանց Պողոսի և Բառնաբասի հետ ուղարկել Անտիոք. Բարսաբբաս կոչված Հուդային և Շիղային, որոնք եղբայրների մեջ առաջնորդներից էին։","23":"Նրանց միջոցով գրեցին այս նամակը. «Առաքյալներից, երեցներից ու եղբայրներից՝ Անտիոքում, Ասորիքում և Կիլիկիայում հեթանոսներից դարձած եղբայրներիդ ողջո՜ւյն։","24":"Քանի որ լսեցինք, որ մեզանից ոմանք, որոնց մենք չէինք հրամայել, խոսքերով խռովեցրել են ձեզ ու ձեր հոգիները խաթարել,","25":"մենք՝ միաբան հավաքվածներս, հարմար համարեցինք ընտրյալ մարդկանց ուղարկել ձեզ մոտ՝ մեր սիրելիների՝ Բառնաբասի և Պողոսի հետ միասին.","26":"մարդիկ, որոնք իրենց կյանքն ընծայել են մեր Տեր Հիսուս Քրիստոսի անվան համար։","27":"Արդ Հուդային ու Շիղային ուղարկեցինք, որպեսզի նրանք էլ խոսքով նույնը հաղորդեն։","28":"Որովհետև Սուրբ Հոգուն և մեզ հաճելի թվաց ավելի ոչ մի բեռ չդնել ձեզ վրա, բացի այս անհրաժեշտներից՝","29":"հեռու մնալ կուռքին զոհաբերվածից և արյունից, խեղդամահ արված կենդանիներից ու պոռնկությունից։ Ձեզ դրանցից հեռու պահելով՝ բարին կգործեք. ո՛ղջ եղեք»։","30":"Եվ նրանք, արձակվելով, իջան Անտիոք, ժողովրդին հավաքեցին և նամակը հանձնեցին։","31":"Ընթերցելով՝ նրանք ուրախացան քաջալերանքի համար։","32":"Հուդան ու Շիղան, քանի որ նույնպես մարգարեներ էին, բազում խոսքերով քաջալերեցին ու ամրապնդեցին եղբայրներին։","33":"Միառժամանակ այնտեղ մնալուց հետո եղբայրների կողմից խաղաղությամբ հետ ուղարկվեցին առաքյալների մոտ։","34":"Բայց Շիղան լավ համարեց այնտեղ մնալ։","35":"Իսկ Պողոսն ու Բառնաբասը Անտիոքում էին մնում և ուրիշ շատերի հետ Տիրոջ խոսքն էին ուսուցանում ու քարոզում։","36":"Սակայն մի քանի օր հետո Պողոսը Բառնաբասին ասաց. «Արի՛ վերադառնանք ու մեր եղբայրներին այցելենք բոլոր այն քաղաքներում, որոնց մեջ Տիրոջ խոսքը քարոզեցինք, և տեսնենք, թե ինչպե՛ս են նրանք ապրում»։","37":"Բառնաբասը ցանկանում էր Մարկոս կոչված Հովհաննեսին էլ վերցնել։","38":"Բայց Պողոսը մտածում էր, որ Պամփյուլիայում իրենցից բաժանվածին և իրենց հետ գործի համար չեկածին չպետք է վերցնեն իրենց հետ։","39":"Եվ նրանց միջև այնպիսի գժտություն եղավ, որ իրարից բաժանվեցին. Բառնաբասը, Մարկոսին վերցնելով, նավարկեց Կիպրոս,","40":"իսկ Պողոսը, Շիղային ընտրելով, ճանապարհ ընկավ՝ եղբայրների կողմից Աստծու շնորհին հանձնվելով։","41":"Եվ Ասորիքում ու Կիլիկիայում շրջելով՝ հաստատում էր եկեղեցիները։"},"16":{"1":"Պողոսը եկավ Դերբե ու Լյուստրա։ Այնտեղ Տիմոթեոս անունով մի աշակերտ կար՝ հրեա հավատացյալ կնոջ և հույն հոր որդի,","2":"որը վկայված էր լյուստրացի և իկոնիացի եղբայրներից։","3":"Պողոսը կամենում էր նրան իր հետ տանել և վերցրեց նրան թլփատեց այդ տեղերում գտնվող հրեաների պատճառով, որովհետև բոլորն էլ գիտեին, որ նրա հայրը հույն էր։","4":"Երբ անցնում էին քաղաքներով, նրանց ավանդում էին պահել այն հրամանները, որոնք պատվիրել էին Երուսաղեմում գտնվող առաքյալներն ու երեցները։","5":"Եկեղեցիները հաստատվում էին հավատի մեջ, և օրեցօր նրանց թիվն ավելանում էր։","6":"Եվ շրջեցին Փռյուգիայում ու գաղատացիների երկրում՝ արգելվելով Սուրբ Հոգուց, որ Ասիայում Աստծու խոսքը չքարոզեն։","7":"Երբ Մյուսիայի սահմանները եկան, ջանում էին դեպի Բյութանիա գնալ, բայց Հիսուսի Հոգին նրանց թույլ չտվեց։","8":"Եվ Մյուսիայով անցնելով՝ իջան Տրովադա։","9":"Գիշերը Պողոսին տեսիլք երևաց. մի մակեդոնացի մարդ կանգնել, նրան աղաչում էր ու ասում. «Անցի՛ր Մակեդոնիա և օգնի՛ր մեզ»։","10":"Երբ այդ տեսիլքը տեսավ, իսկույն ցանկացանք դեպի Մակեդոնիա ելնել՝ համոզված լինելով, որ Տերը մեզ հրավիրեց նրանց ավետարանելու։","11":"Տրովադայից նավարկելով՝ ուղղվեցինք դեպի Սամոթրակե, իսկ հաջորդ օրը՝ Նեապոլիս,","12":"այնտեղից՝ Փիլիպպե, որ Մակեդոնիայի շրջանի գլխավոր քաղաքն է՝ հռոմեական գաղութ։ Այդ քաղաքում մենք մնացինք մի քանի օր։","13":"Շաբաթ օրը քաղաքից դուրս՝ դեպի գետափ գնացինք, որտեղ սովոր էին աղոթք անելու։ Նստած խոսում էինք այնտեղ հավաքված կանանց հետ։","14":"Լիդիա անունով աստվածավախ մի կին, որ Թիատիրա քաղաքից էր և ծիրանի զգեստներ վաճառող, լսում էր. նրա սիրտը Տերն էր բացել, որպեսզի անսար Պողոսի խոսքերին։","15":"Երբ նա և իր ընտանիքը մկրտվեցին, աղաչեց մեզ՝ ասելով. «Եթե ինձ Տիրոջը հավատացող եք համարում, իմ տո՛ւն մտեք, մնացե՛ք»։ Եվ ստիպելով մեզ տարավ։","16":"Երբ մենք աղոթելու էինք գնում, մեզ պատահեց մի աղախին, որ հարցուկ ոգի ուներ և գուշակությամբ իր տերերին մեծ շահ էր բերում։","17":"Նա, Պողոսի և մեր հետևից ընկած, աղաղակում էր ու ասում. «Այս մարդիկ Բարձրյալ Աստծու ծառաներն են, որոնք ձեզ փրկության ճանապարհն են հայտնում»։","18":"Եվ բազում օրեր նույն բանն էր անում։ Իսկ Պողոսը զայրանալով դարձավ ու այդ ոգուն ասաց. «Քեզ հրամայում եմ Հիսուս Քրիստոսի անունով, դրա միջից դո՛ւրս ել»։ Եվ նույն ժամին դուրս ելավ։","19":"Եվ երբ նրա տերերը տեսան, որ իրենց եկամտի հույսը կտրվեց, Պողոսին ու Շիղային բռնելով՝ քարշ տվեցին հրապարակ՝ իշխանների առաջ։","20":"Նրանց տարան զորապետների մոտ ու ասացին. «Այս մարդիկ խռովում են մեր քաղաքը. նրանք հրեաներ են։","21":"Եվ այնպիսի սովորույթներ են քարոզում, որ մեզ՝ հռոմեացիներիս, օրինավոր չէ ո՛չ ընդունել, ո՛չ էլ գործադրել»։","22":"Եվ ամբոխը նրանց վրա նետվեց. զորապետները նրանց զգեստները պատռել տվեցին ու հրամայեցին, որ գանահարեն։","23":"Նրանց շատ վերքեր հասցնելուց հետո բանտարկեցին՝ բանտապետին պատվիրելով, որ նրանց զգուշությամբ պահի։","24":"Նա էլ, այսպիսի հրաման ստանալով, նրանց մեկուսարան գցեց և նրանց ոտքերը կոճղի մեջ ամրացրեց։","25":"Կեսգիշերին Պողոսն ու Շիղան աղոթելով օրհնում էին Աստծուն, իսկ բանտարկյալները նրանց ականջ էին դնում։","26":"Հանկարծ մեծ ցնցում եղավ, այնպես, որ բանտի հիմքերը շարժվեցին, և բոլոր դռներն իսկույն բացվեցին, ու բոլորի կապանքներն արձակվեցին։","27":"Երբ բանտապետը, արթնանալով, բանտի դռները բացված տեսավ, սուրը քաշեց և ուզում էր ինքն իրեն սպանել, որովհետև կարծում էր, թե բանտարկյալները փախել են։","28":"Բայց Պողոսը բարձրաձայն կանչեց և ասաց. «Դու քեզ չվնասե՛ս, որովհետև մենք բոլորս այստեղ ենք»։","29":"Նա լույս խնդրեց, ներս վազեց և դողալով Պողոսի ու Շիղայի առաջ ընկավ։","30":"Նրանց դուրս բերելով՝ ասաց. «Տյա՛րք, ես ի՞նչ պետք է անեմ, որ փրկվեմ»։","31":"Նրանք ասացին. «Հավատա՛ Տեր Հիսուս Քրիստոսին, և կփրկվեք դու և քո ընտանիքը»։","32":"Եվ Տիրոջ խոսքը քարոզեցին նրան և բոլոր նրանց, ովքեր նրա տանն էին։","33":"Գիշերվա նույն ժամին նրանց տարավ, վերքերը լվաց, և իսկույն մկրտվեցին ինքը և բոլոր յուրայինները։","34":"Նրանց իր տուն տանելով՝ սեղան դրեց և իր ամբողջ ընտանիքով ուրախացավ Աստծուն հավատացած լինելու համար։","35":"Լույսը բացվելուն պես զորապետները նվիրակներ ուղարկեցին ու ասացին. «Արձակի՛ր այդ մարդկանց»։","36":"Բանտապետն այս խոսքերը հայտնեց Պողոսին. «Զորապետները մարդ են ուղարկել, որ ազատ արձակվեք։ Արդ դո՛ւրս եկեք և գնացե՛ք խաղաղությամբ»։","37":"Իսկ Պողոսը նրանց ասաց. «Մեզ՝ անմեղներիս, որ հռոմեացի ենք, հրապարակավ ծեծեցին և բանտ նետեցին, հիմա մեզ ծածո՞ւկ են դուրս բերում. իհարկե ո՛չ, թող իրե՛նք գան և մեզ դուրս հանեն»։","38":"Նվիրակներն այդ խոսքերը զորապետներին հաղորդեցին. երբ նրանք լսեցին, որ հռոմեացի են, վախեցան։","39":"Եկան և նրանցից ներողություն խնդրեցին։ Երբ նրանց դուրս հանեցին, աղաչում էին հեռանալ քաղաքից։","40":"Նրանք բանտից դուրս ելան ու մտան Լիդիայի մոտ և եղբայրներին տեսնելով՝ նրանց քաջալերեցին ու հեռացան։"},"17":{"1":"Ամփիպոլիսի և Ապողոնիայի միջով անցնելով՝ եկան Թեսաղոնիկե, որտեղ հրեաների ժողովարան կար։","2":"Պողոսն իր սովորության համաձայն նրանց մոտ մտավ և երեք շաբաթ օրեր նրանց հետ Սուրբ Գրքից խոսեց։","3":"Բացատրում էր և ապացուցում, որ Քրիստոսը պետք է չարչարվեր ու մեռելներից հարություն առներ. «Նա՛ է Քրիստոսը՝ Հիսուսը, որի մասին ես քարոզում եմ ձեզ»։","4":"Նրանցից ոմանք հավատացին և միացան Պողոսին ու Շիղային, ինչպես նաև բազում աստվածավախ հույներ և թվով ոչ պակաս երևելի կանայք։","5":"Իսկ հրեաները նախանձեցին ու հրապարակներում թափառող մի քանի անպիտան մարդկանց հավաքելով ու ամբոխի վերածելով՝ քաղաքը տակնուվրա արեցին և Յասոնի տան վրա հարձակվելով՝ ուզում էին նրանց հրապարակ տանել։","6":"Եվ երբ նրանց այնտեղ չգտան, Յասոնին ու եղբայրներից ոմանց քարշ տվեցին քաղաքի իշխանների մոտ՝ աղաղակելով. «Սրանք, որ աշխարհը տակնուվրա են արել, այստեղ էլ են հասել։","7":"Յասոնը նրանց ընդունել է։ Սրանք բոլորը կայսեր հրամաններին հակառակ են գործում՝ ասելով, որ մեկ ուրիշ թագավոր կա՝ Հիսուսը»։","8":"Եվ վրդովեցրին ժողովրդին ու քաղաքի իշխաններին, որոնք լսում էին այս բաները։","9":"Սակայն Յասոնից և ուրիշներից երաշխիք ստանալով՝ նրանց արձակեցին։","10":"Բայց եղբայրները Պողոսին ու Շիղային գիշերով շտապ ճանապարհ դրեցին դեպի Բերիա, որոնք այնտեղ հասնելուն պես հրեաների ժողովարան գնացին։","11":"Սրանք, որ ավելի ազնիվ էին, քան Թեսաղոնիկեում եղողները, խոսքն ամենայն հոժարությամբ ընդունեցին և ամեն օր քննում էին Սուրբ Գիրքը՝ տեսնելու, թե արդյոք դա այդպե՞ս է։","12":"Արդ նրանցից շատերը հավատացին, ինչպես նաև թվով ոչ պակաս հույն երևելի կանայք ու տղամարդիկ։","13":"Բայց երբ Թեսաղոնիկեի հրեաներն իմացան, որ Բերիայում ևս Պողոսի կողմից Աստծու խոսքը հռչակվեց, այնտեղ էլ եկան՝ ժողովրդին հրահրելու և խռովություն առաջացնելու։","14":"Այդ ժամանակ եղբայրները Պողոսին իսկույն ուղարկեցին, որ մինչև ծովեզր գնա, իսկ Շիղան ու Տիմոթեոսն այնտեղ մնացին։","15":"Պողոսին տանողները նրան հասցրին մինչև Աթենք և հրահանգ ստացան, որ Շիղային ու Տիմոթեոսին ուղղված պատվերը նրանց փոխանցելուց հետո իսկույն նրա մոտ վերադառնան։","16":"Մինչ Պողոսը Աթենքում նրանց էր սպասում, նրա հոգին խռովվում էր՝ քաղաքը կուռքերով լի տեսնելով։","17":"Նա ժողովարանում դիմում էր հրեաներին ու բարեպաշտ մարդկանց, իսկ հրապարակում՝ ամեն օր իրեն հանդիպողներին։","18":"Էպիկուրյան ու ստոյիկյան փիլիսոփաներից ոմանք վիճաբանում էին նրա հետ, իսկ ոմանք ասում էին. «Այս դատարկախոսն ի՞նչ է ուզում ասել»։ Իսկ ուրիշներն էլ՝ «Երևում է՝ ինչ-որ օտար աստվածների քարոզիչ է», որովհետև Հիսուսին և հարությունն էր քարոզում։","19":"Եվ նրան վերցրին տարան Արիսպագոսի առաջ՝ ասելով. «Կարո՞ղ ենք իմանալ, թե քո այդ քարոզած նոր վարդապետությունն ի՛նչ է,","20":"որովհետև մեր ականջներին օտարոտի բաներ ես մատուցում։ Արդ ուզում ենք իմանալ, թե դրանք ի՛նչ են ուզում ասել»։","21":"Քանի որ բոլոր աթենացիներն ու այնտեղ ապրող օտարներն այլ բանով չէին զբաղվում, քան միայն մի ավելի նոր խոսք ասելով կամ լսելով։","22":"Պողոսն Արիսպագոսի մեջտեղում կանգնեց ու ասաց. «Ո՛վ աթենացիներ, տեսնում եմ, որ դուք ամեն առումով պաշտամունքասեր եք,","23":"որովհետև շրջելիս և ձեր պաշտամունքի առարկաները դիտելիս գտա մի զոհասեղան, որի վրա գրված էր՝ \"ԱՆԾԱՆՈԹ ԱՍՏԾՈՒՆ\"։ Արդ, ում դուք առանց ճանաչելու պաշտում եք, ես նրա՛ մասին եմ քարոզում ձեզ։","24":"Այն Աստվածը, որ ստեղծել է այս աշխարհը և դրա մեջ առկա ամեն բան, նա է երկնքի և երկրի Տերը։ Նա ձեռակերտ տաճարներում չի բնակվում,","25":"ոչ էլ մարդկանց ձեռքով է պաշտվում, իբրև թե մի բանի կարոտ է։ Նա է ամեն բանի կյանք ու շունչ և ամեն ինչ տալիս։","26":"Նա մեկ մարդուց ստեղծեց բոլոր ազգերին, որպեսզի բնակվեն ողջ երկրի երեսին. սահմանեց նախակարգյալ ժամանակները և նրանց բնակության սահմանները,","27":"որպեսզի Աստծուն փնտրեն ու թերևս խարխափելով նրան գտնեն, թեև ինքը մեզնից յուրաքանչյուրից հեռու չէ։","28":"Որովհետև մենք նրանով ենք ապրում, շարժվում և կանք, ինչպես ձեր բանաստեղծներից ոմանք ևս ասացին. \"Մենք նրա սերունդն ենք\"։","29":"Արդ, քանի որ Աստծու սերունդն ենք, չպետք է կարծենք, թե աստվածայինը նման է մարդու արվեստով ու երևակայությամբ քանդակված ոսկու կամ արծաթի կամ քարի։","30":"Բայց Աստված, անգիտության ժամանակներն անտեսելով, այժմ մարդկանց պատվիրում է, որ ամեն ոք ամեն տեղ ապաշխարի։","31":"Որովհետև նա սահմանել է մի օր, երբ արդարությամբ պետք է դատի աշխարհն այն մարդու միջոցով, որին նա ընտրել է և որով նա հավաստիացրեց բոլորին՝ նրան մեռելներից հարություն տալով»։","32":"Երբ մեռելների հարության մասին լսեցին, ոմանք ծաղրեցին, ոմանք էլ ասացին. «Այդ մասին քեզանից մեկ ուրիշ անգամ կլսենք»։","33":"Եվ այսպես Պողոսը նրանց միջից դուրս ելավ։","34":"Այնուամենայնիվ ոմանք, նրան միանալով, հավատացին. դրանցից էին Դիոնիսիոս Արիսպագացին ու Դամարիս անունով մի կին և նրանց հետ ուրիշները ևս։"},"18":{"1":"Դրանից հետո Պողոսն Աթենքից մեկնեց և եկավ Կորնթոս։","2":"Նա գտավ Ակյուղաս անունով մի հրեայի՝ ծագումով պոնտացի։ Նա իր կնոջ՝ Պրիսկիղայի հետ նոր էր եկել Իտալիայից՝ համաձայն Կլավդիոսի հրամանի, որով բոլոր հրեաները Հռոմից պետք է հեռանային։ Պողոսը նրանց մոտ գնաց։","3":"Եվ քանի որ արհեստակից էր, նրանց մոտ մնաց ու աշխատում էր, որովհետև արհեստով վրանագործ էին։","4":"Նա ամեն շաբաթ օր քարոզում էր ժողովարանում և համոզում հրեաներին ու հույներին։","5":"Երբ Շիղան ու Տիմոթեոսը Մակեդոնիայից եկան, Պողոսը տրվեց քարոզին՝ հրեաներին վկայելով, որ Հիսուսն է Քրիստոսը։","6":"Բայց քանի որ նրանք ընդդիմանում էին ու հայհոյում, Պողոսը հագուստները թափ տվեց և նրանց ասաց. «Ձեր արյունը ձեր գլուխը. ես անմեղ եմ։ Այսուհետ ես հեթանոսների մոտ եմ գնում»։","7":"Եվ այդտեղից ելավ, մտավ մեկի տունը, որի անունը Տիտիոս Հուստոս էր. մի աստվածապաշտ մարդ, որի տունը ժողովարանին կից էր։","8":"Կրիսպոս ժողովրդապետն իր ամբողջ ընտանիքով հավատաց Տիրոջը. կորնթացիներից շատերը նույնպես, նրան լսելով, հավատացին ու մկրտվեցին։","9":"Եվ Տերը մի գիշեր Պողոսին տեսիլքի մեջ ասաց. «Մի՛ վախեցիր, այլ խոսի՛ր և մի՛ լռիր,","10":"որովհետև ես քեզ հետ եմ. և ոչ ոք քեզ վրա չի հարձակվի՝ քեզ վնասելու, որովհետև այս քաղաքում ես բազում ժողովուրդ ունեմ»։","11":"Պողոսն այստեղ մնաց մեկ տարի և վեց ամիս՝ նրանց ուսուցանելով Աստծու խոսքը։","12":"Աքայիայում հյուպատոս Գաղիոնի օրոք հրեաները միաբանվելով Պողոսի դեմ ելան ու նրան ատյան տարան՝","13":"ասելով. «Սա մարդկանց համոզում է, որ օրենքին հակառակ ձևով Աստծուն պաշտեն»։","14":"Երբ պատրաստվում էր բերանը բացել, Գաղիոնը հրեաներին ասաց. «Հրեանե՛ր, եթե ինչ-որ անիրավություն կամ նենգ խարդախություն լիներ, արժեր, որ ձեզ լսեի։","15":"Բայց եթե հարցը խոսքին, անուններին և ձեր օրենքին է վերաբերում, դո՛ւք տեսեք, որովհետև այդպիսի բաների դատավոր չեմ ուզում լինել»։","16":"Եվ նրանց ատյանից հանեց։","17":"Եվ բոլորը բռնել էին Սոսթենես ժողովրդապետին և ատյանի առաջ ծեծում էին, իսկ Գաղիոնը ոչ էլ մտահոգվում էր դրանց համար։","18":"Իսկ Պողոսը դեռ շատ օրեր մնալուց հետո հրաժեշտ տվեց եղբայրներին և նավարկեց դեպի Ասորիք։ Նրա հետ էին նաև Պրիսկիղան ու Ակյուղասը։ Պողոսը Կենքրայում խուզել էր գլուխը, որովհետև ուխտ էր արել։","19":"Երբ Եփեսոս հասավ, նրանց այնտեղ թողեց, իսկ ինքը, ժողովարան մտնելով, խոսքն ուղղեց հրեաներին։","20":"Եվ նրանք աղաչում էին նրան, որ երկար ժամանակ այնտեղ մնա, բայց նա մերժեց","21":"ու նրանց հրաժեշտ տալով՝ ասաց. «Աստծու կամքով նորից ձեզ մոտ կդառնամ»։ Ապա Եփեսոսից նավարկեց","22":"ու իջավ Կեսարիա, ելավ և ողջունեց եկեղեցուն ու իջավ Անտիոք։","23":"Այստեղ միառժամանակ մնալուց հետո ելավ հերթով շրջելու գաղատացիների երկրում և Փռյուգիայում՝ բոլոր աշակերտներին ամրապնդելով։","24":"Ապողոս անունով մի հրեա՝ ծագումով ալեքսանդրիացի, որ ճարտասան էր և Սուրբ Գրքին քաջածանոթ, եկավ հասավ Եփեսոս։","25":"Նա տեղյակ էր Տիրոջ ճանապարհին և ջերմեռանդ հոգով քարոզում էր ու ճշմարտապես ուսուցանում Հիսուսի մասին։ Նա միայն Հովհաննեսի մկրտությունը գիտեր։","26":"Ապողոսը սկսեց ժողովարանում համարձակ խոսել։ Երբ Ակյուղասն ու Պրիսկիղան նրան լսեցին, նրան իրենց մոտ վերցրին և ճշմարտագույնս բացատրեցին Աստծու ճանապարհը։","27":"Երբ նա ցանկացավ Աքայիա գնալ, եղբայրները, հավանություն տալով, գրեցին աշակերտներին, որ նրան ընդունեն։ Տեղ հասնելուն պես նա Աստծու շնորհով մեծապես նպաստեց հավատացյալներին,","28":"որովհետև բուռն կերպով հրապարակավ հակաճառում էր հրեաներին՝ Սուրբ Գրքի միջոցով ցույց տալով, որ Քրիստոսը Հիսուսն է։"},"19":{"1":"Մինչ Ապողոսը Կորնթոսում էր, Պողոսը վերին կողմերում շրջելուց հետո իջավ Եփեսոս և մի քանի աշակերտներ գտնելով՝","2":"նրանց հարցրեց. «Երբ հավատացիք, Սուրբ Հոգին ընդունեցի՞ք»։ Նրան պատասխանեցին. «Մենք չենք էլ լսել, որ Սուրբ Հոգի կա»։","3":"Պողոսն ասաց. «Արդ ինչո՞վ մկրտվեցիք»։ Նրանք ասացին. «Հովհաննեսի մկրտությամբ»։","4":"Պողոսն ասաց. «Հովհաննեսը ժողովրդին ապաշխարության մկրտությունն էր տալիս և ասում էր, որ հավատան նրան, ով իրենից հետո էր գալու, այսինքն՝ Քրիստոս Հիսուսին»։","5":"Եվ լսելով՝ մկրտվեցին Տեր Հիսուսի անունով։","6":"Երբ Պողոսը ձեռքը նրանց վրա դրեց, Սուրբ Հոգին իջավ նրանց վրա. նրանք տարբեր լեզուներով էին խոսում ու մարգարեանում։","7":"Նրանք բոլորը շուրջ տասներկու հոգի էին։","8":"Ժողովարան մտնելով՝ Պողոսը երեք ամիս համարձակ քարոզում էր՝ համոզիչ ապացույցներ բերելով Աստծու արքայության մասին։","9":"Իսկ երբ ոմանք համառեցին ու չհավատացին՝ ժողովրդի բազմության առաջ նրանց վարդապետությունը վարկաբեկելով, նա բաժանվեց նրանցից, աշակերտներին առանձնացրեց և ամեն օր խոսում էր ոմն Տյուրանի դպրանոցում։","10":"Դա տևեց երկու տարի, մինչև որ Ասիայի բոլոր բնակիչները՝ և՛ հրեաները, և՛ հեթանոսները, լսեցին Տիրոջ խոսքը։","11":"Աստված Պողոսի ձեռքով ոչ պակաս զորավոր գործեր էր անում։","12":"Մինչև իսկ նրա մարմնի վրայից թաշկինակներ ու գլխաշորեր էին տանում՝ հիվանդների վրա դնելու, և ախտերը նրանցից հեռանում էին, ու չար ոգիները դուրս էին գալիս։","13":"Շրջիկ հրեաներից ոմանք էլ, որ երդվեցնողներ էին, փորձեցին չար ոգիներ ունեցողների վրա Տեր Հիսուսի անունը կանչել՝ ասելով. «Երդվեցնում եմ ձեզ այն Հիսուսով, որին Պողոսն է քարոզում»։","14":"Այս անում էին ոմն հրեա քահանայապետ Սկևայի յոթ որդիները։","15":"Բայց չար ոգին պատասխանեց ու ասաց. «Հիսուսին գիտեմ և Պողոսին ճանաչում եմ, իսկ դո՞ւք ով եք»։","16":"Եվ այն մարդը, որի մեջ չար ոգի կար, նրանց վրա հարձակվելով և երկուսին էլ բռնելով, այնպիսի ուժ ցուցաբերեց նրանց նկատմամբ, որ այդ տնից մերկ ու վիրավոր փախան։","17":"Այս բանը հայտնի դարձավ Եփեսոսում բնակվող բոլոր հրեաներին և հեթանոսներին։ Նրանց բոլորի մեջ ահ ընկավ. և Տեր Հիսուսի անունը փառավորվում էր։","18":"Հավատացյալներից շատերը գալիս խոստովանում էին և պատմում իրենց գործերի մասին։","19":"Կախարդությամբ զբաղվողներից շատերը բերում էին գրքերը, բոլորի առաջ այրում։ Հաշվեցին դրանց արժեքն ու տեսան, որ հիսուն հազար արծաթի էր։","20":"Եվ այսպես Տիրոջ զորությամբ խոսքը տարածվում էր ու հզորանում։","21":"Երբ սա կատարվեց, Պողոսը մտադրվեց գնալ Երուսաղեմ՝ Մակեդոնիայով և Աքայիայով անցնելով։ Նա ասում էր. «Իմ այնտեղ գնալուց հետո ես պետք է Հռոմն էլ տեսնեմ»։","22":"Իրեն ծառայողներից երկուսին՝ Տիմոթեոսին ու Երաստոսին, ուղարկեց Մակեդոնիա, իսկ ինքը միառժամանակ մնաց Ասիայում։","23":"Այդ ժամանակ Տիրոջ վարդապետության դեմ մեծ խռովություն եղավ։","24":"Դեմետրիոս անունով մի արծաթագործ Արտեմիսի տաճարի արծաթյա մանրակերտներն էր պատրաստում և վարպետներին ոչ քիչ շահ բերում։","25":"Նա, հավաքելով նրանց և այս արհեստի մասնագետներին, ասաց. «Ո՛վ մարդիկ, դուք ինքներդ գիտեք, որ մեր բարօրությունը կախված է այս գործից։","26":"Տեսնում եք ու լսում, որ այս Պողոսը ոչ միայն եփեսացիներից, այլև գրեթե ամբողջ Ասիայից բազում ժողովրդի համոզելով դարձի է բերել՝ ասելով, որ դրանք ձեռագործներ են, ոչ աստվածներ։","27":"Սա ոչ միայն մեր արհեստն է արհամարհվելու վտանգին ենթարկում, այլև մեծ աստվածուհու՝ Արտեմիսի տաճարն է ոչինչ համարվում։ Եվ պիտի ավերվի նրա մեծությունը ևս, որին ամբողջ Ասիան ու աշխարհն են պաշտում»։","28":"Երբ այս լսեցին, լցվեցին բարկությամբ, աղաղակեցին ու ասացին. «Մեծ է եփեսացիների Արտեմիսը»։","29":"Ողջ քաղաքը խռովությամբ լցվեց. բոլորը միասին խուժեցին թատրոն՝ քարշ տալով Պողոսի ուղեկիցներ Գայիոս և Արիստարքոս Մակեդոնացիներին։","30":"Բայց երբ Պողոսը ցանկացավ ամբոխի մեջ մտնել, աշակերտները նրան չթողեցին։","31":"Ասիայի իշխանավորներից ոմանք, որ նրա բարեկամներն էին, նրա մոտ մարդ ուղարկեցին ու աղաչեցին, որ չգնա թատրոն։","32":"Իսկ ուրիշներն այլ բան էին աղաղակում, որովհետև ժողովը շփոթության մեջ էր. նրանցից շատերը նույնիսկ չգիտեին, թե ինչի՛ համար են հավաքվել։","33":"Եվ այդ ամբոխից առաջ բերեցին Ալեքսանդրոսին։ Երբ հրեաները նրան առաջ քաշեցին, Ալեքսանդրոսը ձեռքը շարժեց և ուզում էր ամբոխի առջև խոսել։","34":"Երբ իմացան, որ հրեա է, բոլորը միաձայն մոտ երկու ժամ աղաղակում էին. «Մեծ է եփեսացիների Արտեմիսը»։","35":"Քաղաքի ատենադպիրը ամբոխին հանդարտեցնելուց հետո ասաց. «Եփեսացինե՛ր, ո՞վ է այն մարդը, որ չգիտի՝ Եփեսոսը քաղաքն է Արտեմիս մեծ աստվածուհու տաճարի և երկնքից ընկած նրա կուռքի։","36":"Եվ քանի որ դա անկասկած այդպես է, դուք պետք է հանդարտվեք և ոչ մի հանդգնություն չանեք։","37":"Դուք այստեղ բերեցիք այդ մարդկանց, որոնք ո՛չ մեհյանն են կողոպտել, ո՛չ էլ մեր աստվածուհուն հայհոյել։","38":"Ուրեմն եթե Դեմետրիոսն ու նրա հետ եղող վարպետները մեկի դեմ որևէ բան ունեն, թող ատյանները տանեն, որտեղ հյուպատոսներ կան, և թող միմյանց ամբաստանեն։","39":"Իսկ եթե ձեր խնդիրը մի ուրիշ բանի համար է, թող օրինավոր ժողովում վճռվի։","40":"Որովհետև մենք էլ ենք վտանգված մեղադրվելու այսօրվա խռովության համար, որը պատահեց առանց որևէ պատճառի։ Արդ այս հավաքի համար չենք կարողանալու որևէ պատասխան տալ»։ Եվ այս ասելով՝ ժողովն արձակեց։"},"20":{"1":"Աղմուկը դադարելուց հետո Պողոսն աշակերտներին կանչեց, քաջալերեց նրանց և հրաժեշտ տալով՝ ելավ Մակեդոնիա գնաց։","2":"Այդ կողմերում շրջելով ու նրանց բազում խոսքերով քաջալերելով՝ եկավ Հունաստան,","3":"որտեղ մնաց երեք ամիս. մինչ պատրաստվում էր Ասորիք նավարկել, հրեաները նրա դեմ դավ նյութեցին, ուստի որոշեց Մակեդոնիայով վերադառնալ։","4":"Եվ մինչև Ասիա նրա հետ էին Պյուռոսի որդի Սոպատրոս Բերիացին, թեսաղոնիկեցիներից Արիստարքոսն ու Սեկունդոսը, Գայիոս Դերբացին ու Տիմոթեոսը և ասիացիներ Տյուքիկոսն ու Տրոփիմոսը։","5":"Սրանք նախապես էին գնացել և մեզ սպասում էին Տրովադայում։","6":"Իսկ մենք Բաղարջակերաց տոնի օրերից հետո նավարկեցինք Փիլիպպեից և հինգ օրից հասանք նրանց մոտ՝ Տրովադա, որտեղ կանգ առանք յոթ օր։","7":"Շաբաթվա առաջին օրը, երբ հավաքվել էինք հաց կտրելու, Պողոսը խոսում էր նրանց հետ, որովհետև հաջորդ օրը գնալու էր, և խոսքը մինչև կեսգիշեր երկարեց։","8":"Վերնատանը, որտեղ մենք հավաքվել էինք, բավականաչափ լապտերներ կային։","9":"Եվտիքոս անունով մի երիտասարդ նստել էր պատուհանին և խոր քուն մտել։ Մինչ Պողոսը շարունակում էր խոսել, նա, խոր քնով բռնված, տան երրորդ հարկից ցած ընկավ, ու նրան մեռած վերցրին։","10":"Պողոսը, իջնելով, նրա վրա ընկավ ու գիրկն առնելով նրան՝ ասաց. «Մի՛ անհանգստացեք, որովհետև հոգին իր մեջ է»։","11":"Այնուհետև վեր ելավ, հացը կտրեց ու կերավ և մինչև առավոտ շատ բաներ ևս խոսեց, ապա մեկնեց։","12":"Իսկ պատանուն կենդանի բերեցին և մեծապես մխիթարվեցին։","13":"Իսկ մենք առաջանալով նավ նստեցինք և ուղղվեցինք դեպի Ասոս, որտեղից պետք է վերցնեինք Պողոսին, որովհետև այդպես էր պատվիրել, քանի որ ինքը ցամաքով էր գնալու։","14":"Երբ նա Ասոսում մեզ հանդիպեց, նրան վերցրինք և Միտիլենե եկանք։","15":"Այդտեղից նավարկելով՝ հաջորդ օրը հասանք Խիոսի դիմացը, մյուս օրը՝ Սամոս, հետևյալ օրը՝ Միլետոս.","16":"որովհետև Պողոսը որոշել էր Եփեսոսի մոտով նավարկել, որպեսզի Ասիայում ժամանակ չկորցներ, քանի որ շտապում էր, որ եթե հնարավոր լիներ, Պենտեկոստեի օրը Երուսաղեմում լիներ։","17":"Միլետոսից մարդ ուղարկելով Եփեսոս՝ կանչեց եկեղեցու երեցներին։","18":"Երբ Պողոսի մոտ եկան, նրանց ասաց. «Դուք գիտեք, թե առաջին օրից ի վեր, երբ Ասիա եկա, այդ ամբողջ ժամանակ ինչպե՛ս ձեզ հետ ապրեցի՝","19":"ծառայելով Տիրոջը ամենայն խոնարհությամբ, արտասուքով ու փորձություններով, որ հրեաների նենգությունների պատճառով պատահեցին ինձ։","20":"Ես բնավ չհրաժարվեցի ձեզ պատմել այն, ինչ օգտակար է, և ձեզ ուսուցանել ինչպես հրապարակավ, այնպես էլ տներում։","21":"Հրեաներին և հեթանոսներին վկայություն տվեցի՝ Աստծու առաջ ապաշխարության և մեր Տեր Հիսուս Քրիստոսի հանդեպ հավատի։","22":"Այժմ ահա հոգու մղումով գնում եմ Երուսաղեմ ու չգիտեմ, թե այնտեղ ինձ ի՛նչ է պատահելու։","23":"Բայց Սուրբ Հոգին ամեն քաղաքի մեջ վկայում է ինձ ու ասում, որ կապանքներ և նեղություններ են սպասում ինձ։","24":"Բայց ես իմ կյանքը ոչ մի բանով այդքան արժեքավոր չեմ համարում, որքան այն, որ ուրախությամբ կատարեմ իմ ընթացքը և ծառայությունը, որ Տեր Հիսուսից ստանձնել եմ Աստծու շնորհի Ավետարանը վկայելու համար։","25":"Այժմ ահա ես գիտեմ, որ դուք բոլորդ, որոնց մեջ շրջեցի՝ Աստծու արքայությունը քարոզելով, իմ երեսն այլևս չեք տեսնի։","26":"Դրա համար այսօր վկայում եմ ձեր առաջ, որ բոլորիդ արյունից ես մաքուր եմ,","27":"որովհետև ես չքաշվեցի ձեզ հաղորդելու Աստծու կամքն ամբողջությամբ։","28":"Զգո՛ւյշ եղեք ինքներդ ձեզ համար և ամբողջ հոտի, որի վրա Սուրբ Հոգին վերակացուներ կարգեց ձեզ, որպեսզի հովվեք Աստծու եկեղեցին, որ նա ձեռք բերեց իր արյունով։","29":"Ես գիտեմ, որ իմ հեռանալուց հետո ձեր մեջ հափշտակող գայլեր կգան, որոնք հոտին չեն խնայի։","30":"Իսկ ձեր միջից դուրս կգան մարդիկ, որոնք թյուր բաներ կխոսեն, որպեսզի աշակերտներին իրենց հետևից տանեն։","31":"Դրա համար էլ արթո՛ւն կացեք՝ հիշելով, որ երեք տարի գիշեր-ցերեկ յուրաքանչյուրիդ անդադար խրատեցի արտասուքներով։","32":"Այժմ ձեզ հանձնում եմ Աստծուն ու նրա շնորհի խոսքին, որ կարող է կառուցել և ձեզ ժառանգություն տալ բոլոր սրբացածների հետ։","33":"Ես ձեզանից ոչ ոքի արծաթը կամ ոսկին կամ հագուստը չցանկացա։","34":"Դուք ինքներդ գիտեք, որ այս ձեռքերն իմ կարիքները հոգացին, նաև նրանց կարիքները, ովքեր ինձ հետ էին։","35":"Ամեն բան ձեզ ցույց տվեցի, որ այսպես պետք է աշխատել և հոգ տանել տկարներին ու Տեր Հիսուսի խոսքը հիշել, որ ասաց. \"Ավելի երանելի է տալը, քան առնելը\"»։","36":"Եվ երբ այս ասաց, բոլորի հետ ծնկի եկավ ու աղոթեց։","37":"Բոլորն էլ շատ էին լաց լինում և Պողոսի վզովն ընկած՝ համբուրում էին նրան։","38":"Ցավում էին մանավանդ այն խոսքի համար, որ ասում էր, թե իր երեսն այլևս չեն տեսնելու։ Եվ նրան ճանապարհ գցեցին դեպի նավ։"},"21":{"1":"Մենք, նրանցից բաժանվելով, դուրս եկանք և ուղիղ գնացինք Կոս, հաջորդ օրը՝ Հռոդոս, այնտեղից էլ՝ Պատարա։","2":"Մի նավ գտանք, որ Փյունիկե էր գնում. նրա մեջ մտանք ու գնացինք։","3":"Եվ երբ Կիպրոսը երևաց, այն ձախ կողմում թողեցինք ու նավը դեպի Ասորիք ուղղեցինք, իջանք Տյուրոս, որովհետև նավը բեռն այնտեղ պետք է թափեր։","4":"Եվ աշակերտներին գտնելով՝ յոթ օր այնտեղ մնացինք. նրանք Սուրբ Հոգու միջոցով Պողոսին ասում էին, որ Երուսաղեմ չելնի։","5":"Եվ երբ այնտեղ լրացան մեր այդ օրերը, դուրս եկանք, գնացինք մեր ճամփան. բոլորը՝ կանանցով ու երեխաներով, մեզ ճանապարհ գցեցին մինչև քաղաքից դուրս։ Եվ ծովեզրին ծունկ չոքեցինք, աղոթեցինք","6":"ու հրաժեշտ տվեցինք։ Ապա նավ բարձրացանք, իսկ նրանք վերադարձան իրենց տները։","7":"Մենք էլ, ծովային ճանապարհորդությունն ավարտելով, Տյուրոսից դուրս եկանք, հասանք Պտողեմայիս, եղբայրներին ողջույն տվեցինք ու նրանց մոտ մի օր մնացինք։","8":"Հաջորդ օրը Պողոսը և մենք՝ նրա ընկերները, այդտեղից դուրս եկանք Կեսարիա և Փիլիպպոս ավետարանչի տունը մտնելով, որն այն յոթից մեկն էր, նրա մոտ մնացինք։","9":"Նա չորս կույս աղջիկներ ուներ, որոնք մարգարեություն էին անում։","10":"Եվ երբ մենք այնտեղ շատ օրեր մնացինք, Հրեաստանից մի մարգարե իջավ, անունը՝ Ագաբոս։","11":"Նա մեզ մոտ եկավ, Պողոսի գոտին վերցրեց, իր ձեռքերն ու ոտքերը կապեց և ասաց. «Սուրբ Հոգին այսպես է ասում. \"Այն մարդուն, որի գոտին է սա, հրեաները Երուսաղեմում այսպես կկապեն ու հեթանոսների ձեռքը կմատնեն\"»։","12":"Եվ երբ այս լսեցինք, մենք և այնտեղացիներն էլ աղաչում էինք, որ Երուսաղեմ չելնի։","13":"Այդ ժամանակ Պողոսն ասաց. «Ի՞նչ եք անում, լաց եք լինում և սիրտս ճմլում. որովհետև ես ոչ միայն բանտարկվելու, այլ Տեր Հիսուս Քրիստոսի անվան համար Երուսաղեմում մեռնելու էլ պատրաստ եմ»։","14":"Եվ երբ նա չհամոզվեց, լուռ մնացինք ու ասացինք. «Տիրոջ կամքը թող լինի»։","15":"Այդ օրերից հետո պատրաստված Երուսաղեմ ելանք։","16":"Այն կեսարացի աշակերտներից էլ մեզ հետ եկան. մեզ Մնասոն անունով մի կիպրացի մարդու՝ վաղ ժամանակից աշակերտի մոտ տարան, որ նրա մոտ մնայինք։","17":"Եվ երբ մենք Երուսաղեմ հասանք, եղբայրները մեզ ուրախությամբ ընդունեցին։","18":"Հաջորդ օրը Պողոսը մեզ հետ Հակոբոսի մոտ գնաց. բոլոր երեցներն էլ ներկա էին։","19":"Եվ նրանց ողջույն տալով՝ մեկ առ մեկ պատմում էր, ինչ որ Աստված հեթանոսների մեջ արեց իր ծառայությամբ։","20":"Նրանք, լսելով, փառաբանում էին Տիրոջը և ասում էին նրան. «Եղբա՛յր, տեսնո՞ւմ ես, քանի՜ բյուր հավատացյալ հրեաներ կան. ամենքն էլ օրենքի նախանձախնդիրներ են։","21":"Բայց քո մասին իմացել են, որ հեթանոսների մեջ եղող բոլոր հրեաներին սովորեցնում ես Մովսեսի օրենքից հրաժարվել՝ ասելով, որ իրենց երեխաներին չթլփատեն և հրեական ավանդույթները չպահեն։","22":"Հիմա ի՞նչ կլինի. անպատճառ բազմությունը կհավաքվի, որովհետև կլսեն, որ եկել ես։","23":"Հիմա ա՛յս արա, ինչ որ քեզ ասում ենք. մեր մեջ չորս մարդիկ կան, որոնք իրենց անձերի վրա երդում են արել։","24":"Նրանց վերցրո՛ւ և նրանց հետ սրբվի՛ր. նրանց ծախսերը հոգա՛, որ գլուխներն ածիլեն, ու բոլորը գիտենան, թե ինչ որ քո մասին իմացել են, ճիշտ չէ, այլ որ դու էլ ես շարունակում օրենքը պահել։","25":"Բայց այն հավատացյալ դարձած հեթանոսների վերաբերյալ մենք լուր ուղարկեցինք՝ որոշելով, որ նրանք այդպիսի բան չպահեն, այլ միայն զգուշանան կուռքին զոհվածից, արյունից, խեղդվածից և պոռնկությունից»։","26":"Այդ ժամանակ Պողոսն այն մարդկանց վերցրեց, հաջորդ օրը նրանց հետ սրբվելուց հետո մտավ տաճար՝ սրբության օրերի ավարտվելն իմաց տալու, որպեսզի նրանցից յուրաքանչյուրի համար ընծա մատուցվի։","27":"Եվ երբ այն յոթ օրերն ավարտվելու մոտ էին, ասիացի հրեաները նրան տաճարում տեսան. ողջ ամբոխը նրա գլխին հավաքվեց, և նրան բռնելով՝","28":"աղաղակում էին. «Ո՛վ իսրայելացի մարդիկ, օգնեցե՜ք. սա այն մարդն է, որ ժողովրդին, օրենքին և այստեղին հակառակ՝ ամենուրեք բոլորին քարոզում է, մինչև իսկ հույների էլ է տաճար մտցրել և այս սուրբ տեղը պղծել»։","29":"Որովհետև Տրոփիմոս Եփեսացուն առաջ նրա հետ քաղաքում տեսել էին և կարծում էին, թե Պողոսը նրան տաճար է մտցրել։","30":"Եվ ամբողջ քաղաքը ոտքի ելավ. ժողովուրդը հավաքվեց. Պողոսին բռնելով տաճարից դուրս քաշեցին, և շուտով դռները փակվեցին։","31":"Եվ երբ ուզում էին նրան սպանել, գնդի հազարապետին լուր հասավ, որ ամբողջ Երուսաղեմը տակնուվրա է եղել։","32":"Նա էլ իսկույն զինվորներ ու հարյուրապետներ վերցրեց, վազեց նրանց վրա։ Նրանք էլ երբ հազարապետին ու զինվորներին տեսան, դադարեցին Պողոսին ծեծելուց։","33":"Այդ ժամանակ հազարապետը մոտեցավ, բռնեց նրան ու հրամայեց, որ երկու շղթայով կապեն, և հարցնում էր, թե ո՛վ է և ի՛նչ է արել։","34":"Ամբոխի մեջ ամեն մեկը մի բան էր աղաղակում։ Երբ ամբոխի շփոթից չկարողացավ ստույգն իմանալ, հրամայեց բերդ տանել նրան։","35":"Եվ երբ աստիճաններին հասավ, պետք եղավ, որ զինվորներն ամբոխի բռնության պատճառով նրան վերցնեն բերեն,","36":"որովհետև ժողովրդի բազմությունը հետևից գնում էր՝ աղաղակելով. «Մա՛հ դրան»։","37":"Եվ քանի դեռ Պողոսը բերդ մտնելու վրա էր, հազարապետին ասաց. «Արդյոք կարելի՞ է, որ ես քեզ հետ խոսեմ»։ Նա էլ ասաց. «Հունարեն գիտե՞ս։","38":"Արդյոք դու այն եգիպտացին չե՞ս, որ այս օրերից առաջ խռովություն գցեց և չորս հազար ավազակաբարո մարդիկ անապատ հանեց»։","39":"Եվ Պողոսն ասաց. «Ես հրեա մարդ եմ՝ Կիլիկիայի Տարսոնից, ոչ թե աննշան քաղաքի քաղաքացի։ Աղաչում եմ քեզ, ինձ թո՛ւյլ տուր, որ այդ ժողովրդի հետ խոսեմ»։","40":"Եվ երբ նա թույլ տվեց, Պողոսը, աստիճանների վրա կանգնած, ժողովրդին ձեռքով նշան արեց։ Երբ կատարյալ լռություն տիրեց, եբրայերեն լեզվով խոսքն ուղղեց ու ասաց."},"22":{"1":"«Եղբայրնե՛ր ու հայրե՛ր, այժմ լսե՛ք իմ՝ ձեզ ուղղված պատասխանը»։","2":"Երբ լսեցին, որ եբրայերեն լեզվով իրենց դիմեց, առավել ևս հանդարտվեցին։ Եվ ասաց.","3":"«Ես հրեա մարդ եմ՝ ծնված Կիլիկիայի Տարսոնում, դաստիարակված այս քաղաքում, կրթված Գամաղիելի ոտքերի մոտ՝ մեր հայրենի օրենքի ճշտության համաձայն։ Նախանձահույզ էի Աստծու նկատմամբ, ինչպես այսօր դուք բոլորդ։","4":"Ես մինչև մահ հալածում էի այս ուղղությունը՝ տղամարդկանց ու կանանց կապելով և բանտերի մատնելով։","5":"Ինչպես իմ մասին վկայում են քահանայապետը և ողջ ծերակույտը, նրանցից եղբայրներին ուղղված նամակներն առնելով՝ գնում էի Դամասկոս, որպեսզի այնտեղ գտնվողներին ևս կապելով՝ բերեի Երուսաղեմ՝ պատժվելու։","6":"Երբ գնալիս Դամասկոսին էի մոտենում, կեսօրվա մոտ հանկարծ երկնքից շուրջս ուժեղ լույս փայլատակեց։","7":"Ես ընկա գետնին և մի ձայն լսեցի, որ ինձ ասում էր. \"Սավո՛ւղ, Սավո՛ւղ, ինչո՞ւ ես հալածում ինձ\"։","8":"Ես պատասխանեցի. \"Ո՞վ ես, Տե՛ր\"։ Եվ ինձ ասաց. \"Ես Հիսուս Նազովրեցին եմ, որին դու հալածում ես\"։","9":"Ինձ հետ եղողները լույսը տեսնում էին, սակայն ինձ հետ խոսողի ձայնը չէին լսում։","10":"Ես ասացի. \"Ի՞նչ պետք է անեմ, Տե՛ր\"։ Տերն ինձ ասաց. \"Վեր կաց գնա՛ Դամասկոս, և այնտեղ քեզ կասվի այն ամենի մասին, ինչ քեզ համար որոշված է, որ անես\"։","11":"Եվ քանի որ այդ լույսի փայլի պատճառով չէի տեսնում, ինձ հետ եղողները ձեռքիցս բռնեցին, ու ես մտա Դամասկոս։","12":"Անանիա անունով մի մարդ՝ օրենքին հավատարիմ և Դամասկոսում ապրող բոլոր հրեաների կողմից վկայված,","13":"եկավ կանգնեց ինձ մոտ ու ասաց. \"Սավո՛ւղ եղբայր, վերստին ստացի՛ր տեսողությունդ\"։ Եվ ես նույն պահին տեսողությունս վերագտա ու տեսա նրան։","14":"Եվ նա ինձ ասաց. \"Մեր հայրերի Աստվածը քեզ նախասահմանեց, որ իր կամքը ճանաչես, Արդարին տեսնես ու նրա բերանից ձայնը լսես,","15":"որպեսզի բոլոր մարդկանց առաջ նրա վկան լինես այն բաների մասին, որ տեսար ու լսեցիր։","16":"Այժմ ինչո՞ւ ես հապաղում. վե՛ր կաց, մկրտվի՛ր ու լվա՛ քո մեղքերը՝ նրա անունը կանչելով\"։","17":"Երբ ես Երուսաղեմ վերադարձա և տաճարում աղոթում էի, մտքի հափշտակության մեջ ընկա.","18":"ես տեսա նրան, որ ինձ ասում էր. \"Փութա՛, շտապ դո՛ւրս գնա Երուսաղեմից, որովհետև իմ մասին քո վկայությունը չեն ընդունելու\"։","19":"Իսկ ես ասացի. \"Տե՛ր, նրանք գիտեն, որ ես էի բանտ նստեցնում և ժողովարաններում գանահարել տալիս քեզ հավատացողներին։","20":"Եվ երբ քո վկայի՝ Ստեփանոսի արյունը թափվում էր, ես ինքս նրա մոտ կանգնած էի, հավանություն էի տվել նրա սպանությանը և պահում էի նրան սպանողների հագուստները\"։","21":"Բայց նա ինձ ասաց. \"Գնա՛, որովհետև ես քեզ ուղարկելու եմ հեռու՝ հեթանոսների մոտ\"»։","22":"Մինչև այս խոսքը նրան լսում էին, բայց հետո իրենց ձայնը բարձրացրին ու ասացին. «Երկրից վերացրո՛ւ այդպիսի մեկին, որովհետև դա չպետք է ապրի»։","23":"Եվ աղաղակելով հանում էին հագուստները, վեր գցում և փոշին օդ ցանում։","24":"Հազարապետը հրամայեց նրան բերդ մտցնել՝ ասելով. «Ծեծելով հարցաքննե՛ք դրան, որպեսզի իմանամ, թե ի՛նչ հանցանքի համար են նրա դեմ այդպես աղաղակում»։","25":"Երբ նրան կաշեփոկերով պինդ կապեցին, Պողոսն իր մոտ կանգնած հարյուրապետին ասաց. «Թույլատրվո՞ւմ է ձեզ ծեծել հռոմեացի և չդատված մարդուն»։","26":"Երբ հարյուրապետը լսեց, մոտեցավ հազարապետին ու ասաց. «Ի՞նչ ես պատրաստվում անել, որովհետև այս մարդը Հռոմի քաղաքացի է»։","27":"Հազարապետը մոտեցավ ու նրան ասաց. «Ասա՛ ինձ, դու հռոմեացի՞ ես». նա պատասխանեց. «Այո՛»։","28":"Եվ հազարապետն ասաց. «Ես մեծ դրամագլխով եմ ստացել այս քաղաքացիությունը»։ Իսկ Պողոսն ասաց. «Ես ծնունդով իսկ քաղաքացի եմ»։","29":"Ուստի նրանք, ովքեր հարցաքննելու էին, իսկույն հեռացան նրանից։ Հազարապետը ևս վախեցավ, երբ իմացավ, որ հռոմեացի է, որովհետև կապանքի տակ էր պահել նրան։","30":"Հաջորդ օրը հազարապետը, ցանկանալով հրեաների ամբաստանության մասին ճշմարտությունն իմանալ, Պողոսին կապերից արձակեց և հրամայեց կանչել քահանայապետներին ու հավաքել ամբողջ ատյանը։ Իսկ Պողոսին բերեց և նրանց առաջ կանգնեցրեց։"},"23":{"1":"Պողոսը հայացքն ուղղեց ատյանին ու ասաց. «Եղբայրնե՛ր, ես մինչև այսօր Աստծու առաջ ապրել եմ ամենայն ուղղամտությամբ»։","2":"Անանիա քահանայապետը մոտը կանգնածներին հրամայեց, որ խփեն նրա բերանին։","3":"Այդ ժամանակ Պողոսն ասաց նրան. «Աստված պիտի խփի քեզ, սպիտակեցրա՛ծ պատ. դու նստել ես ինձ օրենքի համաձայն դատելու և օրենքը խախտելով՝ հրամայում ես, որ ինձ խփե՞ն»։","4":"Եվ ներկա գտնվողներն ասացին. «Աստծու քահանայապետի՞ն ես նախատում»։","5":"Պողոսն ասաց. «Եղբայրնե՛ր, ես չգիտեի, որ քահանայապետ է, որովհետև գրված է. \"Քո ժողովրդի իշխանին չչարախոսես\" (Ելք 22.28)»։","6":"Երբ Պողոսն իմացավ, որ ատյանում մի մասը սադուկեցիներն են, իսկ մյուս մասը՝ փարիսեցիները, բացականչեց. «Եղբայրնե՛ր, ես փարիսեցի եմ ու փարիսեցու որդի. ահա դատվում եմ նաև մեռելների հարության հույսի համար»։","7":"Երբ նա այս ասաց, փարիսեցիների ու սադուկեցիների միջև երկպառակություն ծագեց, և բազմությունը պառակտվեց։","8":"Որովհետև սադուկեցիներն ասում են, որ հարություն չկա. ո՛չ հրեշտակ կա, ո՛չ էլ հոգի, իսկ փարիսեցիները հավատում են երկուսին էլ։","9":"Եվ մեծ աղմուկ եղավ. փարիսեցիների կողմից որոշ դպիրներ վեր կացան և հակառակվելով՝ ասացին. «Այս մարդու մեջ ոչ մի չարություն չենք գտնում. թերևս նրա հետ հոգի կամ մի հրեշտակ խոսեց»։","10":"Խռովությունն այնքան թեժացավ, որ հազարապետը, վախենալով, որ գուցե Պողոսը նրանց կողմից պատառ-պատառ արվի, զինվորներին հրամայեց իջնել, նրանց միջից Պողոսին վերցնել ու բերդ տանել։","11":"Հաջորդ գիշեր Տերը կանգնեց նրա մոտ ու ասաց. «Քաջալերվի՛ր, Պողո՛ս, որովհետև ինչպես ինձ համար Երուսաղեմում վկայեցիր, այնպես էլ Հռոմում պետք է վկայես»։","12":"Երբ լուսացավ, հրեաներից ոմանք, հավաքվելով, երդվեցին, որ մինչև Պողոսին չսպանեն, ո՛չ ուտեն և ո՛չ էլ խմեն։","13":"Միմյանց հետ այս երդումն անողները քառասունից ավելի էին։","14":"Նրանք մոտեցան քահանայապետներին ու ծերերին և ասացին. «Մենք երդում արեցինք ոչինչ չուտելու, մինչև Պողոսին չսպանենք։","15":"Այժմ դուք հազարապետին ատյանի հետ միասին հայտնե՛ք, որ վաղը նրան ձեզ մոտ իջեցնի, իբր թե ուզում եք նրա մասին ավելի ստույգ բաներ իմանալ. իսկ մենք նախքան նրա մոտենալը պատրաստ ենք նրան վերացնելու»։","16":"Երբ Պողոսի քրոջ որդին նրանց այս դավադրությունը լսեց, մտավ բերդ ու պատմեց Պողոսին։","17":"Պողոսը հարյուրապետներից մեկին իր մոտ կանչեց ու ասաց. «Այս պատանուն հազարապետի մո՛տ տար, որովհետև նրան հայտնելու բան ունի»։","18":"Եվ նա, պատանուն վերցնելով, հազարապետի մոտ տարավ ու ասաց. «Բանտարկյալ Պողոսն ինձ կանչեց՝ խնդրելով, որ այս պատանուն քեզ մոտ բերեմ. քեզ ասելու բան ունի»։","19":"Հազարապետը, նրա ձեռքից բռնելով, մի կողմ գնաց ու առանձին հարցրեց. «Ի՞նչ ունես ինձ հայտնելու»։","20":"Նա ասաց. «Հրեաները պայմանավորվեցին քեզ խնդրելու, որ վաղը Պողոսին ատյան իջեցնես, իբր թե ուզում են նրա մասին ավելի մանրամասն քննություն կատարել։","21":"Արդ դու նրանց մի՛ լսիր, որովհետև նրանցից ավելի քան քառասուն մարդ դավ են նյութել նրա դեմ ու երդվել, որ ո՛չ ուտեն և ո՛չ էլ խմեն, մինչև չսպանեն Պողոսին։ Այժմ պատրաստ՝ քո հրամանին են սպասում»։","22":"Ապա հազարապետն արձակեց պատանուն՝ պատվիրելով. «Ոչ ոքի չասես, որ այս բաների մասին ինձ հայտնել ես»։","23":"Նա կանչեց հարյուրապետներից երկուսին ու ասաց. «Երկու հարյուր զինվոր, յոթանասուն հեծյալ և երկու հարյուր նիզակավո՛ր պատրաստեք, որ գիշերվա երրորդ ժամին գնան Կեսարիա։","24":"Պատրաստե՛ք նաև գրաստներ, որ Պողոսին նստեցնեն և ապահով հասցնեն Փելիքս կուսակալի մոտ»։","25":"Գրեց նաև մի նամակ, որի բովանդակությունն այս էր.","26":"«Կլավդիոս Լյուսիասից Ձերդ գերազանցություն Փելիքս կուսակալին ողջո՜ւյն։","27":"Այս մարդուն, որին հրեաները բռնել էին, և նրանց կողմից սպանվելու մոտ էր, զինվորներով վրա հասա, ազատեցի՝ իմանալով, որ հռոմեացի է։","28":"Ցանկանալով իմանալ նրա հանցանքը, որի համար նրան ամբաստանում էին, նրան նրանց ատյան իջեցրի։","29":"Նրան իրենց օրենքի մի՛ հարցում ամբաստանված գտա, սակայն մեռնելու կամ բանտարկվելու արժանի ոչ մի հանցանք չուներ։","30":"Երբ տեղեկացա, որ հրեաների կողմից այդ մարդու դեմ դավ կա, նրան ուղարկեցի քեզ մոտ և հրամայեցի, որ չարախոսողները նրա մասին քո առաջ խոսեն։ Ո՛ղջ եղիր»։","31":"Զինվորները, իրենց տրված հրամանի համաձայն Պողոսին վերցնելով, գիշերով տարան Անտիպատրիս։","32":"Հաջորդ օրը հեծյալներին թողեցին, որ նրա հետ գնան, իսկ իրենք բերդ վերադարձան։","33":"Նրանք մտան Կեսարիա, նամակը հանձնեցին կուսակալին, իսկ Պողոսին կանգնեցրին նրա առաջ։","34":"Երբ կուսակալը կարդաց, հարցրեց, թե ո՛ր նահանգից է, և երբ տեղեկացավ, որ Կիլիկիայից է,","35":"ասաց. «Քեզ կլսեմ, երբ քեզ ամբաստանողներն էլ ներկա գտնվեն»։ Եվ հրամայեց, որ նրան Հերովդեսի պալատում պահեն։"},"24":{"1":"Հինգ օր հետո Անանիա քահանայապետը մի քանի ծերերի և Տերտյուղոս անունով մի ճարտասանի հետ եկավ։ Կուսակալին հաղորդեցին Պողոսի մասին։","2":"Նրան կանչելուց հետո Տերտյուղոսն սկսեց ամբաստանել և ասել. «Քանի որ քո շնորհիվ մեծ խաղաղություն ենք գտել, և քո հոգածությամբ այս ազգի մեջ շատ բաներ են կարգավորվել,","3":"ամեն բանի համար և ամենուրեք քեզնից շնորհակալ ենք և մեծապես երախտապարտ, ո՛վ պատվական Փելիքս։","4":"Բայց որպեսզի քեզ ավելորդ նեղություն չպատճառեմ, խնդրում եմ, որ քո համբերատարությամբ լսես մեր հակիրճ խոսքը։","5":"Մենք գտանք, որ այս մարդը ամբողջ աշխարհում գտնվող բոլոր հրեաներին ապականողն ու խռովեցնողն է և նազովրեցիների աղանդի առաջնորդը։","6":"Նա փորձեց նույնիսկ տաճարը պղծել, և նրան բռնեցինք։","8":"Դու ինքդ էլ կարող ես նրան վերաքննելով տեղեկանալ այն բոլոր բաների մասին, որոնց համար նրան ամբաստանում ենք»։","9":"Հրեաներն էլ հավանություն տվեցին և ասացին. «Այդպես է»։","10":"Երբ կուսակալը նրան նշան արեց, որ խոսի, Պողոսը պատասխանեց. «Գիտեմ, որ դու շատ տարիներ ի վեր այս ազգի դատավորն ես, ուստի հոժարությամբ եմ իմ մասին պատասխան տալիս։","11":"Դու կարող ես իմանալ, որ տասներկու օրից ավելի չէ, ինչ ես բարձրացել եմ Երուսաղեմ՝ երկրպագություն անելու։","12":"Ինձ ո՛չ տաճարում են որևէ մարդու հետ խոսելիս կամ շուրջս ամբոխ հավաքելիս գտել, ո՛չ ժողովարաններում, ո՛չ էլ քաղաքում։","13":"Եվ ոչ էլ կարող են քեզ ապացուցել այն, ինչի համար ինձ այժմ ամբաստանում են։","14":"Բայց սա եմ քեզ խոստովանում, որ համաձայն ա՛յն ճանապարհի, որին \"հերձված\" են կոչում, այդպե՛ս եմ պաշտում մեր հայրերի Աստծուն՝ հավատալով այն ամենին, ինչ գրված է օրենքում և մարգարեների մեջ։","15":"Հույս ունեմ առ Աստված, ինչպես որ նրանք են ակնկալում, որ արդարների և մեղավորների հարություն է լինելու։","16":"Դրա համար ինքս միշտ ջանք եմ թափում, որ Աստծու և մարդկանց առաջ մաքուր խիղճ ունենամ։","17":"Արդ բազում տարիներ հետո եկա, որ իմ ազգին ողորմություն տամ ու ընծաներ մատուցեմ։","18":"Մինչ դրանցով էի զբաղված, ինձ գտան տաճարում մաքրվելիս՝ ո՛չ ամբոխի հետ և ո՛չ էլ խռովության մեջ։","19":"Ասիայի հրեաներից ոմանք պետք է քո առաջ գային ու ամբաստանեին, եթե իմ դեմ մի բան ունեին։","20":"Կամ հենց սրանք թող ասեն, թե ի՛նչ անիրավություն գտան իմ մեջ, մինչ ատյանի առաջ կանգնած էի,","21":"բացի այն մի խոսքից, որ նրանց մեջ կանգնած աղաղակեցի. \"Մեռելների հարություն առնելու համար եմ ես այսօր դատվում ձեր կողմից\"»։","22":"Փելիքսը, ավելի ստույգ իմանալով այս ուղղության մասին, հետաձգեց գործը և ասաց. «Ձեր վերաբերյալ գործը կքննվի, երբ Լյուսիաս հազարապետն իջնի»։","23":"Նա հրամայեց հարյուրապետին Պողոսին պահել, բայց ազատություն տալ և նրա յուրայիններից ոչ մեկին չարգելել նրան ծառայելու։","24":"Մի քանի օր հետո Փելիքսը եկավ իր կնոջ՝ Դրուսիլայի հետ, որը հրեա էր։ Կանչեց Պողոսին ու նրանից լսեց Հիսուս Քրիստոսի հանդեպ հավատի մասին։","25":"Մինչ Պողոսը արդարության, ժուժկալության և գալիք դատաստանի մասին էր խոսում, Փելիքսը զարհուրելով ասաց. «Դու առայժմ գնա՛, երբ ժամանակ լինի, քեզ կկանչեմ»։","26":"Միևնույն ժամանակ նա ակնկալում էր, որ Պողոսն իրեն դրամ կտա, և դրա համար հաճախ էր կանչում նրան ու հետը զրուցում։","27":"Երկու տարին լրանալուց հետո Փելիքսին հաջորդեց Պորկիոս Փեստոսը։ Փելիքսը, ցանկանալով հրեաներին շնորհ անել, Պողոսին կալանքի տակ թողեց։"},"25":{"1":"Երբ Փեստոսը նահանգ եկավ, երեք օր հետո Կեսարիայից Երուսաղեմ բարձրացավ։","2":"Քահանայապետներն ու հրեաների գլխավորները Պողոսի մասին զեկուցեցին նրան և խնդրում էին,","3":"որ շնորհ անի և Պողոսին Երուսաղեմ կանչի, որովհետև դարան էին պատրաստել՝ ճանապարհին նրան սպանելու համար։","4":"Սակայն Փեստոսը պատասխանեց, որ Պողոսը Կեսարիայում պիտի պահվի, և ինքն էլ շուտով այնտեղ է գնալու։","5":"«Ձեզանից ովքեր կարող են,- ասաց,- թող ինձ հետ իջնեն, ու եթե այդ մարդու վրա որևէ հանցանք կա, թող ամբաստանեն նրան»։","6":"Եվ ութ կամ տասն օրից ոչ ավելի այնտեղ մնալով՝ Կեսարիա իջավ։ Հաջորդ օրն ատյան նստեց ու հրամայեց Պողոսին բերել։","7":"Երբ նա եկավ, Երուսաղեմից իջած հրեաները նրա շուրջը հավաքվեցին և Պողոսի դեմ բազում մեղադրանքներ բերեցին, որոնք չէին կարողանում ապացուցել,","8":"որովհետև նա պատասխանում էր. «Ո՛չ հրեաների օրենքի, ո՛չ տաճարի, ո՛չ էլ կայսրի դեմ որևէ մեղք չեմ գործել»։","9":"Բայց Փեստոսը, ցանկանալով հրեաներին շնորհ անել, Պողոսին ասաց. «Ուզո՞ւմ ես Երուսաղեմ բարձրանալ և այդ բաների համար իմ առաջ այնտեղ դատվել»։","10":"Պողոսն ասաց. «Ես կանգնած եմ կայսեր ատյանի առաջ, որտեղ պետք է դատվեմ։ Հրեաներին ոչ մի անիրավություն չեմ արել, և ինքդ էլ քաջ գիտես։","11":"Եթե մեղավոր եմ և մահվան արժանի բան եմ կատարել, մեռնելուց չեմ խուսափում։ Իսկ եթե ոչինչ չկա, որի համար սրանք ամբաստանում են ինձ, ոչ ոք ինձ չի կարող դրանց հանձնել։ Կայսրին եմ դիմում»։","12":"Այդժամ Փեստոսը խորհրդի հետ խոսելուց հետո պատասխանեց. «Կայսրին դիմեցիր, կայսրի մոտ էլ կգնաս»։","13":"Մի քանի օր անց Ագրիպպաս թագավորն ու Բերնիկեն իջան Կեսարիա՝ Փեստոսին ողջունելու։","14":"Այստեղ բավականաչափ օրեր անցկացնելուց հետո Փեստոսը Պողոսի մասին տեղեկացրեց թագավորին ու ասաց. «Այստեղ Փելիքսի կողմից բանտարկված մի մարդ է մնացել,","15":"որի մասին ինձ քահանայապետներն ու հրեաների երեցները տեղեկացրին, երբ Երուսաղեմում էի։ Նրանք նրա պատիժն են պահանջում։","16":"Նրանց պատասխանեցի. \"Հռոմեացիների համար օրինական չէ որևէ մարդու հանձնել ատյանի, մինչև ամբաստանյալն իր առաջ իրեն մեղադրողներին չունենա և այդ մեղադրանքին պատասխանելու հնարավորությունը չստանա\"։","17":"Երբ նրանց հետ այստեղ եկա, առանց հապաղելու հաջորդ օրն իսկ ատյան նստելով՝ հրամայեցի բերել այդ մարդուն։","18":"Նրա դեմ առաջադրված մեղադրանքներից ոչ մեկը ես լուրջ չեմ համարում։","19":"Դրանք իրենց կրոնի հետ կապված որոշ խնդիրներ են ոմն մեռած Հիսուսի վերաբերյալ, որի մասին Պողոսն ասում էր, թե կենդանի է։","20":"Երբ այսպիսի խնդիրների քննության համար տարակուսանքի մեջ ընկա, ասացի, թե արդյոք ցանկանո՞ւմ է Երուսաղեմ գնալ և այդ բաների համար այնտեղ դատվել։","21":"Բայց երբ Պողոսը պահանջեց, որ ինքը պետք է պահվի Օգոստափառ կայսեր վճռի համար, ես հրամայեցի նրան պահել, մինչև կայսեր մոտ ուղարկեմ»։","22":"Ագրիպպասը Փեստոսին ասաց. «Ես էլ կուզենայի լսել այդ մարդուն»։ Նա ասաց. «Վաղը կլսես»։","23":"Հաջորդ օրը, երբ Ագրիպպասն ու Բերնիկեն մեծ հանդիսավորությամբ եկան ու հազարապետների և քաղաքի պատվավոր մարդկանց հետ ատյան մտան, Փեստոսը հրամայեց, ու Պողոսին բերեցին։","24":"Փեստոսն ասաց. «Ագրիպպա՛ս թագավոր և մեզ հետ ներկա ամե՛նքդ. տեսնում եք սրան, որի համար հրեա ամբողջ ժողովուրդն ինձ մոտ եկավ՝ թե՛ Երուսաղեմում և թե՛ այստեղ՝ աղաղակելով, որ նա չպետք է կենդանի մնա։","25":"Բայց ես հասկացա, որ նա մահվան արժանի ոչինչ չի արել։ Իսկ քանի որ նա դիմել էր Օգոստափառին, մտածեցի, որ այնտեղ ուղարկեմ նրան։","26":"Նրա մասին ճշգրիտ որևէ բան չունեմ տիրոջս գրելու։ Այդ պատճառով նրան ձեր առաջ բերեցի և մանավանդ քո՛ առաջ, ո՛վ Ագրիպպաս թագավոր, որ վերաքննելով՝ գրելու որևէ բան ունենամ,","27":"քանի որ ինձ անտրամաբանական է թվում որևէ բանտարկյալի ուղարկել՝ առանց նրա դեմ հանցանք նշելու»։"},"26":{"1":"Ագրիպպասը Պողոսին ասաց. «Քեզ թույլատրվում է, որ քո մասին խոսես»։ Այդ ժամանակ Պողոսը ձեռքը մեկնեց ու սկսեց իրեն պաշտպանել.","2":"«Հրեաների կողմից իմ մասին արված բոլոր ամբաստանությունների համար, ո՛վ Ագրիպպաս թագավոր, ինձ երանելի եմ համարում, որ այսօր քո առաջ պաշտպանելու եմ ինձ,","3":"մանավանդ որ գիտակ ես հրեաների բոլոր սովորույթներին ու խնդիրներին. դրա համար աղաչում եմ, որ ինձ համբերությամբ լսես։","4":"Բոլոր հրեաները տեղյակ են իմ կյանքին, որ մանկությունիցս ի վեր ի սկզբանե եղել եմ իմ ազգի մեջ Երուսաղեմում։","5":"Վաղուց գիտեն, եթե ցանկանան վկայել, որ ես որպես փարիսեցի ապրել եմ մեր կրոնի խստագույն օրենքների համաձայն։","6":"Եվ հիմա կանգնել ու դատվում եմ Աստծուց մեր հայրերին տրված խոստումի հույսի համար,","7":"որին մեր տասներկու ցեղերը, գիշեր ու զօր անդադար պաշտելով, ակնկալել են հասնել։ Այդ հույսի համար եմ ամբաստանվում հրեաների կողմից, ո՛վ Ագրիպպաս արքա։","8":"Ինչո՞ւ է ձեզ անհավատալի թվում, որ Աստված մեռելներին հարություն է տալիս։","9":"Ես հենց ինքս անհրաժեշտ էի համարում Հիսուս Նազովրեցու անվանը հակառակ շատ բաներ անել,","10":"որ և արեցի Երուսաղեմում. քահանայապետներից իշխանություն ստանալով՝ սրբերից շատերին էի բանտարկում և նրանց սպանությանը հավանություն էի տալիս։","11":"Բոլոր ժողովարաններում շատ անգամներ նրանց պատժելով՝ բռնադատում էի, որ հայհոյեին, և նրանց դեմ առավել ևս մոլեգնելով՝ հալածում էի մինչև օտար քաղաքներ։","12":"Երբ քահանայապետների իշխանությամբ ու հանձնարարությամբ Դամասկոս էի գնում,","13":"կեսօրին ճանապարհին տեսա, ո՛վ արքա, որ երկնքից արեգակի լուսավորությունից առավել մի լույս փայլատակեց իմ և ինձ հետ գնացողների շուրջը։","14":"Երբ մենք բոլորս գետնին ընկանք, լսեցի մի ձայն, որ եբրայերեն լեզվով ինձ ասում էր. \"Սավո՛ւղ, Սավո՛ւղ, ինչո՞ւ ես ինձ հալածում. քեզ համար դժվար է մեխին ոտքով խփել\"։","15":"Իսկ ես ասացի. \"Ո՞վ ես, Տե՛ր\"։ Նա ասաց. \"Ես Հիսուսն եմ, որին դու հալածում ես։","16":"Բայց վե՛ր կաց և կանգնի՛ր ոտքերիդ վրա, որովհետև քեզ նրա համար երևացի, որ քեզ նշանակեմ պաշտոնյա և վկա այն բաների, ինչ դու տեսար, և այն բաների, որոնցով պիտի երևամ քեզ՝","17":"ազատելու այն ժողովրդից ու հեթանոսներից, որոնց մեջ քեզ ուղարկում եմ,","18":"որպեսզի նրանց աչքերը բացես, խավարից դեպի լույսը և սատանայի իշխանությունից դեպի Աստված նրանց դարձնես, որպեսզի նրանք իմ հանդեպ ունեցած հավատով մեղքերի թողություն և սրբերի հետ ժառանգություն ստանան\"։","19":"Ուստի, ո՛վ Ագրիպպաս արքա, ես երկնային տեսիլքին անհնազանդ չեղա,","20":"այլ նախ նրանց, ովքեր Դամասկոսում, Երուսաղեմում և Հրեաստանի բոլոր գավառներում էին, ինչպես նաև հեթանոսներին քարոզեցի, որ ապաշխարեն և դեպի Աստված դառնան՝ ապաշխարության արժանի գործեր կատարելով։","21":"Այս բաների համար հրեաներն ինձ տաճարում բռնելով փորձեցին սպանել։","22":"Արդ Աստծուց օգնություն հասավ, և ես մինչև այսօր կանգնած փոքրին ու մեծին վկայում եմ՝ ոչինչ չասելով այն բաներից դուրս, ինչ մարգարեներն ու Մովսեսն են խոսել լինելիք դեպքերի մասին,","23":"որ Քրիստոսը չարչարվելու է և մեռելներից առաջինը հարություն առած լինելով՝ ժողովրդին ու հեթանոսներին լույս է ավետարանելու»։","24":"Մինչ Պողոսը այս պատասխանն էր տալիս, Փեստոսը բարձրաձայն ասաց. «Ցնորվում ես, Պողո՛ս, քո բազում գիտելիքները քեզ մոլագարության են տանում»։","25":"Իսկ Պողոսն ասաց. «Չեմ ցնորվում, նորի՛ն վսեմություն Փեստոս, այլ ճշմարտության և զգաստության խոսքեր եմ արտասանում։","26":"Որովհետև այս բաներին թագավորն էլ է տեղյակ, որին և համարձակ ասում եմ. չեմ կարծում, թե սրանցից որևէ բան նրանից ծածկված լինի, քանի որ դա խուլ անկյունում չի եղել։","27":"Մարգարեներին հավատո՞ւմ ես, ո՛վ Ագրիպպաս արքա. գիտեմ, որ հավատում ես»։","28":"Ագրիպպասը Պողոսին ասաց. «Քիչ է մնում՝ ինձ էլ համոզես, որ քրիստոնյա դառնամ»։","29":"Պողոսն ասաց. «Աստծուց կխնդրեի, որ ոչ միայն դու, այլ նաև բոլոր նրանք, ովքեր այսօր ինձ լսում են, քիչ թե շատ այնպիսին լինեին, ինչպիսին ես եմ, միայն առանց այս կապանքների»։","30":"Եվ երբ նա այս ասաց, թագավորը, կուսակալը, Բերնիկեն ու նրանց հետ բոլոր նստածները վեր կացան։","31":"Գնալիս իրար հետ խոսում էին և ասում. «Այս մարդը մեռնելու կամ կապանքների արժանի բան չի արել»։","32":"Բայց Ագրիպպասը Փեստոսին ասաց. «Այս մարդուն կարելի էր արձակել, եթե կայսրին դիմած չլիներ»։"},"27":{"1":"Երբ որոշվեց՝ դեպի Իտալիա նավարկենք, Պողոսին ու մի քանի այլ կալանավորների հանձնեցին կայսերական գնդից Հուլիոս անունով մի հարյուրապետի։","2":"Նստելով ադրամինտական մի նավ, որ Ասիայի կողմերն էր գնալու, ճանապարհ ընկանք։ Մեզ հետ էր նաև Արիստարքոս Մակեդոնացին Թեսաղոնիկեից։","3":"Հաջորդ օրն իջանք Սիդովն, և Հուլիոսը, Պողոսի նկատմամբ մարդասիրություն ցուցաբերելով, թույլ տվեց նրան բարեկամների մոտ գնալ՝ խնամք ստանալու։","4":"Այդտեղից նավարկելով՝ գնացինք Կիպրոսի ներքևի կողմով՝ քամու հակառակ ուղղությամբ փչելու պատճառով։","5":"Ապա նավարկելով Կիլիկիան և Պամփյուլիան ողողող ծովով՝ իջանք Լիկիայի Միռա քաղաքը։","6":"Այնտեղ հարյուրապետը, գտնելով Ալեքսանդրիայի մի նավ, որ Իտալիա էր գնում, մեզ այնտեղ նստեցրեց։","7":"Բազում օրեր դանդաղ նավարկելով՝ հազիվ հասանք Կնիդոսի կողմերը։ Քանի որ քամին մեր հակառակ կողմից էր, Կրետեի ներքևով նավարկեցինք դեպի Սալմովնի հրվանդան։","8":"Նրա եզերքով դժվարությամբ անցնելով՝ եկանք մի տեղ, որ «Գեղեցիկ նավահանգիստ» էր կոչվում, որի մոտ էր Լասեա քաղաքը։","9":"Եվ քանի որ բավականաչափ ժամանակ էր անցել, նավարկելը վտանգավոր կլիներ, իսկ ծոմապահության ժամանակն էլ արդեն անցել էր, Պողոսը խրատ էր տալիս՝","10":"ասելով նրանց. «Մարդի՛կ, տեսնում եմ, որ այս նավարկությունը նեղությամբ ու մեծ վնասով է լինելու ոչ միայն բեռի ու նավի, այլ նաև մեր կյանքի համար»։","11":"Բայց հարյուրապետը նավապետին ու նավատիրոջն ավելի էր լսում, քան Պողոսի խոսքերին։","12":"Քանի որ նավահանգիստը ձմեռն անցկացնելու համար անհարմար էր, մեծամասնությունը մտածեց այդտեղից հեռանալ, որպեսզի միգուցե կարողանային Փյունիկե հասնել և ձմեռել կրետացիների այդ նավահանգստում, որը դեպի հարավ-արևմուտք և դեպի ցամաք էր նայում։","13":"Երբ հարավի մեղմ քամին փչեց, կարծեցին, թե իրենց նպատակին կհասնեն, և խարիսխները վերցնելով՝ ինչքան հնարավոր է դեպի Կրետե նավարկեցին։","14":"Շատ ժամանակ չէր անցել, երբ կղզու կողմից մի մրրկահողմ բարձրացավ, որ «Եվրացիկլոն» էր կոչվում։","15":"Երբ նավը քշվեց և մրրկահողմին չկարողացավ դիմանալ, նավի կառավարումը թողեցինք և տարուբերվում էինք։","16":"Եվ ընթանալով դեպի մի կղզի, որ Կավդա էր կոչվում, մակույկը հազիվ կարողացանք փրկել։","17":"Օգնության միջոցներով այն նավի վրա քաշեցինք, ապա պարաններ օգտագործեցին և նավի տակից անցկացնելով՝ կապեցին. վախենալով, որ Սիրտիսի ծովածոցի մեջ կընկնեն, խարիսխը ծովը իջեցրին և այդպես տարուբերվում էին։","18":"Մինչ մենք փոթորկից շատ նեղություն էինք կրում, հաջորդ օրը նրանք սկսեցին բեռները ծովը գցել։","19":"Երրորդ օրը նրանք իրենց ձեռքով ծովը նետեցին նավի գործիքները։","20":"Երբ բազում օրեր ո՛չ արև էր երևում, ո՛չ էլ աստղեր, վատ եղանակն էլ շարունակվում էր, փրկվելու մեր ողջ հույսը կտրվեց։","21":"Քանի որ արդեն շատ օրեր քաղցած էին, այդ ժամանակ Պողոսը, նրանց մեջ կանգնելով, ասաց. «Մարդի՛կ, դուք պետք է ինձ լսեիք ու Կրետեից չելնեիք և այս նեղությունից ու վտանգից կխուսափեիք։","22":"Իսկ այժմ ձեզ խրատում եմ, որ քաջալերվեք, որովհետև բացի նավից, ձեզնից ոչ մեկի կյանքին վնաս չպիտի հասնի։","23":"Քանի որ այս գիշեր ինձ երևաց հրեշտակը այն Աստծու, որին ես պատկանում եմ և պաշտում եմ,","24":"և ասաց. \"Մի՛ վախեցիր, Պողո՛ս, դու պետք է կայսեր առաջ կանգնես, և ահա բոլոր նրանց, ովքեր քեզ հետ նավարկում են, Աստված քեզ է շնորհել\"։","25":"Դրա համար քաջալերվե՛ք, մարդի՛կ, որովհետև հավատում եմ Աստծուն, որ կլինի այնպես, ինչպես որ ինձ ասվեց։","26":"Սակայն պետք է մի կղզի ընկնենք»։","27":"Արդեն տասնչորսերորդ գիշերը եղավ, ինչ մենք Ադրիական ծովում դեռևս տարուբերվում էինք։ Կեսգիշերին նավավարները կարծեցին, թե ինչ-որ ցամաք ենք հասել։","28":"Ջրի խորությունը չափող գունդը գցելով՝ քսան գրկաչափ խորություն գտան. մի փոքր էլ առաջանալով՝ նորից գցեցին և տասնհինգ գրկաչափ գտան։","29":"Վախենալով, որ թերևս խութերի մեջ ընկնեն, հետևի կողմից չորս խարիսխ ցած գցեցին և սպասում էին լուսանալուն։","30":"Բայց քանի որ նավավարներն ուզում էին նավից փախչել, մակույկն իջեցրին ծով այն պատճառաբանությամբ, թե իբր առջևի կողմից էլ են խարիսխ գցելու։","31":"Պողոսը հարյուրապետին ու զինվորներին ասաց. «Եթե դրանք նավի մեջ չմնան, դուք չեք կարող փրկվել»։","32":"Այդ ժամանակ զինվորները մակույկի պարանները կտրեցին և թողեցին, որ ծովն ընկնի։","33":"Լուսադեմին Պողոսը բոլորին խնդրում էր, որ կերակուր ընդունեն՝ ասելով. «Այսօր տասնչորսերորդ օրն է, ինչ դուք սպասելով քաղցած եք մնացել և ոչինչ չեք կերել։","34":"Դրա համար աղաչում եմ ձեզ, որ կերակուր ընդունեք, որովհետև դա ձեր փրկության համար է. քանի որ ձեզանից ոչ մեկի գլխից մի մազ չի կորչելու»։","35":"Այս ասելով՝ հաց վերցրեց, բոլորի առաջ Աստծուն գոհություն հայտնեց, կտրեց ու սկսեց ուտել։","36":"Եվ բոլորը քաջալերվեցին, ու իրենք էլ սնվեցին։","37":"Նավի մեջ բոլորս միասին երկու հարյուր յոթանասունվեց հոգի էինք։","38":"Կերակուրից հագենալով՝ նավը թեթևացրին՝ ցորենը ծովը թափելով։","39":"Երբ լույսը բացվեց, մի անծանոթ ցամաք տեսան։ Նկատեցին մի ծովածոց, որ ծովափ ուներ. մտածում էին, թե միգուցե հնարավոր լիներ նավն այնտեղ հասցնել։","40":"Խարիսխները կտրելով ծովը գցեցին, ղեկերի կապերը թուլացրին, առագաստը բացեցին և քամուն հանձնեցին ծովափի ուղղությամբ։","41":"Ընկնելով ծովը երկու մասի բաժանող մի տեղ՝ նավը դուրս քաշեցին. նավի առաջակողմը հատակին խրվեց և անշարժ մնաց, իսկ հետնակողմն ալիքների սաստկությունից քանդվում էր։","42":"Զինվորները որոշել էին կալանավորներին սպանել, որպեսզի ոչ ոք լողալով չփախչեր։","43":"Բայց հարյուրապետը, կամենալով Պողոսին փրկել, նրանց այդ մտադրությունից հետ պահեց ու հրամայեց, որ նախ լողալ կարողացողները ջուրը նետվեն ու ցամաք ելնեն,","44":"իսկ մնացածներից ոմանք՝ տախտակների վրա, ոմանք էլ՝ նավից ինչ-որ բանի վրա. և այդպես բոլորն էլ ցամաք ելան և փրկվեցին։"},"28":{"1":"Երբ փրկվեցինք, այն ժամանակ իմացանք, որ այդ կղզու անունը Մելիտե էր։","2":"Տեղացիները մեր հանդեպ բացառիկ մարդասիրություն ցույց տվեցին. խարույկ վառեցին, մեզ բոլորիս ընդունեցին, քանի որ անձրև էր ու ցուրտ։","3":"Երբ Պողոսը շատ չոր փայտեր էր հավաքել և կրակի վրա էր դնում, տաքությունից մի իժ դուրս եկավ ու նրա ձեռքից կախվեց։","4":"Երբ տեղացիները տեսան նրա ձեռքից կախված սողունին, միմյանց ասացին. «Այս մարդը հաստատ մարդասպան է, որ ծովից փրկվեց, բայց արդարությունը նրան չթողեց, որ ապրի»։","5":"Պողոսը սողունին կրակի մեջ թափ տվեց, և իրեն ոչ մի վատ բան չպատահեց։","6":"Իսկ նրանք սպասում էին, որ նա կուռչի կամ հանկարծակի մեռած կընկնի։ Երբ շատ սպասեցին ու տեսան, որ նրան ոչ մի վնաս չեղավ, իրենց կարծիքը փոխեցին և ասացին. «Սա մի աստված է»։","7":"Այդ տեղի շրջակայքում գտնվում էին կղզու Պոպլիոս անունով գլխավորի գյուղերը։ Նա մեզ երեք օրով սիրով իր մոտ ընդունեց։","8":"Այնպես եղավ, որ Պոպլիոսի հայրը ջերմով ու արյունալուծից հիվանդացել, պառկել էր։ Պողոսը նրա մոտ մտավ, աղոթեց, ձեռքերը դրեց նրա վրա ու բժշկեց նրան։","9":"Երբ այս պատահեց, կղզում ապրող ուրիշ հիվանդներ էլ գալիս էին և բժշկվում։","10":"Նրանք մեծ հանդիսավորությամբ մեզ պատվեցին, և երբ մեկնում էինք, ինչ որ պետք էր, տվեցին։","11":"Երեք ամիս հետո բարձրացանք մի նավ, որ ձմեռել էր այդ կղզում։ Այն ալեքսանդրիական էր և դիոսկուրյանների նշանն ուներ։","12":"Սիրակուսա իջնելով՝ երեք օր այնտեղ մնացինք։","13":"Այնտեղից պտույտ գործելով՝ հասանք Ռեգիոն։ Երբ մեկ օր հետո հարավի քամին փչեց, երկու օրում հասանք Պոտիոլոս,","14":"որտեղ և գտանք եղբայրների, որոնք խնդրեցին, որ յոթ օր իրենց մոտ մնանք։ Այնուհետև եկանք Հռոմ։","15":"Եվ այնտեղից եղբայրները, մեր մասին լսած լինելով, մեզ ընդառաջ ելան մինչև Ապպիոսի առևտրի պալատն ու Երեք պանդոկները։ Երբ Պողոսը նրանց տեսավ, Աստծուն գոհություն հայտնեց ու քաջալերվեց։","16":"Երբ Հռոմ մտանք, Պողոսին հրամայվեց իր պահապան զինվորի հետ առանձին մնալ։","17":"Երեք օր հետո Պողոսը հրավիրեց հրեաների գլխավորներին։ Երբ եկան, նրանց ասաց. «Եղբայրնե՛ր, ժողովրդին կամ նախնյաց ավանդույթներին հակառակ ոչինչ չգործած՝ Երուսաղեմից կալանավորված՝ հռոմեացիների ձեռքը մատնվեցի։","18":"Նրանք ինձ դատելուց հետո կամեցան բաց թողնել, որովհետև իմ մեջ մահապատժի արժանի ոչ մի հանցանք չկար։","19":"Բայց երբ հրեաներն առարկում էին, ստիպված եղա կայսրին դիմել. ոչ թե որ իմ ազգին ամբաստանելու բան ունեի։","20":"Այս պատճառով է, որ այժմ խնդրեցի ձեզ տեսնել ու խոսել, որովհետև Իսրայելի հույսի համար եմ ես այս շղթայով կապված»։","21":"Իսկ նրանք ասացին նրան. «Մենք քո վերաբերյալ Հրեաստանից ո՛չ նամակ ենք ստացել, ո՛չ էլ եղբայրներից որևէ մեկը եկել ու քո մասին վատ բան է պատմել կամ խոսել։","22":"Բայց կցանկանայինք քեզանից լսել, թե ի՛նչ ես կարծում, որովհետև այդ աղանդի մասին մեզ հայտնի է, որ ամենուրեք դրա դեմ հակաճառություն կա»։","23":"Նրա հետ որոշակի օր նշանակելուց հետո բազում մարդիկ եկան նրա օթևան, որոնց վկայում էր Աստծու արքայության մասին և առավոտից մինչև երեկո նրանց համոզում Հիսուսի մասին Մովսեսի օրենքով ու մարգարեներով։","24":"Ոմանք հավատում էին նրա խոսքերին, իսկ ոմանք չէին հավատում։","25":"Եվ իրար հետ համաձայնության չգալով՝ հեռանում էին, երբ Պողոսն այս խոսքն ասաց. «Սուրբ Հոգին Եսայի մարգարեի միջոցով մեր հայրերի հետ լավ խոսեց","26":"և ասաց. \"Գնա՛ այս ժողովրդի մոտ և ասա՛. \"Դուք կլսեք, բայց չեք հասկանա, և կնայեք, բայց չեք տեսնի։","27":"Որովհետև այս ժողովրդի սիրտը կարծրացել է, և իրենց ականջներով ծանր են լսում և իրենց աչքերը փակել են, որպեսզի երբեք աչքերով չտեսնեն, ականջներով չլսեն ու սրտով չիմանան, դարձի չգան, և ես չբժշկեմ նրանց\" (Ես. 6.9-10)։","28":"Արդ թող ձեզ հայտնի լինի, որ Աստծու փրկությունը ուղարկվեց հեթանոսներին, և նրանք էլ կլսեն»։","30":"Եվ Պողոսն ամբողջ երկու տարի ապրեց իր ծախսով և ընդունում էր բոլոր իր մոտ եկողներին։","31":"Քարոզում էր Աստծու արքայությունը և ամենայն համարձակությամբ անխափան ուսուցանում էր Տեր Հիսուս Քրիստոսի մասին։"}};
